{"format":"forge-project","version":1,"app":"game-forge-v2","entry":"index.html","files":[{"path":"index.html","type":"text/html","text":"<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Age of Empires — Dawn of the Ancient World</title>
  <link rel="stylesheet" href="css/style.css">
</head>
<body>
  <div id="menu">
    <div class="menu-inner">
      <header>
        <h1>AGE OF EMPIRES</h1>
        <div class="subtitle">Dawn of the Ancient World · Stone Age to Iron Age</div>
      </header>
      <div class="setup">
        <section class="col wide">
          <label class="row">Your name <input id="m-name" value="Pharaoh" maxlength="20"></label>
          <div class="label">Choose your civilisation</div>
          <div id="civ-cards"></div>
        </section>
        <section class="col">
          <div class="label">Opponents (computer)</div>
          <div id="opp-list"></div>
          <button id="add-opp" class="small">+ Add opponent</button>
          <div class="label">Game settings</div>
          <label class="row">Map <select id="m-map"></select></label>
          <label class="row">Size <select id="m-size"><option value="small">Small</option><option value="medium" selected>Medium</option><option value="large">Large</option></select></label>
          <label class="row">Resources <select id="m-res"><option value="low" selected>Standard</option><option value="medium">Medium</option><option value="high">High</option></select></label>
          <label class="row">Population limit <select id="m-pop"><option>50</option><option selected>75</option><option>100</option><option>150</option></select></label>
          <label class="row">Wonder countdown <select id="m-wonder"><option value="240">4 minutes</option><option value="360" selected>6 minutes</option><option value="600">10 minutes</option></select></label>
          <label class="row">Teams <select id="m-teams"><option value="ffa">Free for all</option><option value="ais">All computers vs you</option></select></label>
          <label class="row">Game speed <select id="m-speed"><option value="1">1×</option><option value="1.5" selected>1.5×</option><option value="2">2×</option><option value="3">3×</option></select></label>
          <label class="row chk"><input type="checkbox" id="m-reveal"> Reveal map</label>
          <label class="row chk"><input type="checkbox" id="m-spectate"> Spectate (computers only)</label>
          <div class="btns">
            <button id="start-btn" class="primary">Start Game</button>
            <button id="howto-btn">How to Play</button>
          </div>
        </section>
      </div>
      <footer>Vanilla HTML5 canvas · no downloads · all art and sound generated in your browser</footer>
    </div>
  </div>

  <div id="game">
    <canvas id="view"></canvas>
    <div id="hud-top"></div>
    <div id="wonder-banners"></div>
    <div id="msg-log"></div>
    <div id="scoreboard"></div>
    <div id="hud-bottom">
      <div id="minimap-box"><canvas id="minimap" width="200" height="200"></canvas></div>
      <div id="sel-info"></div>
      <div id="cmd-grid"></div>
    </div>
    <div id="tooltip"></div>
  </div>

  <div id="overlay"><div id="overlay-box"></div></div>
  <div id="loading"><div>Shaping the ancient world…</div></div>

  <script src="js/util.js"></script>
  <script src="js/data.js"></script>
  <script src="js/map.js"></script>
  <script src="js/pathfinding.js"></script>
  <script src="js/game.js"></script>
  <script src="js/ai.js"></script>
  <script src="js/sound.js"></script>
  <script src="js/sprites.js"></script>
  <script src="js/render.js"></script>
  <script src="js/ui.js"></script>
  <script src="js/input.js"></script>
  <script src="js/main.js"></script>
</body>
</html>
