#overlay-box { background: linear-gradient(#3a2812, #1e1408); border: 2px solid #c09050; border-radius: 6px; padding: 14px 22px; max-width: min(1000px, 94vw); max-height: 90vh; overflow: auto; box-shadow: 0 0 40px #000; }
#overlay-box h2 { text-align: center; color: #f2cf7a; margin: 4px 0 10px; font-size: 28px; }
