"},{"path":"js/ai.js","type":"text/javascript","text":"'use strict';
/* Computer opponent. It plays by the same rules as the human: every resource it spends is carried
   home by its own villagers or fishing boats, it must own the prerequisite buildings to advance,
   it pays for everything through the normal queue/placement APIs, and it attacks in growing waves. */

const AI_DIFF = {
  easy:   { think: 2.0, vil: [12, 18, 22, 26], army: [2, 6, 10, 14], firstWave: 1080, waveGap: 420, waveBase: 4, waveGrow: 2, research: 0.45, towers: 1, wonderChance: 0.0, vilDefend: false },
  normal: { think: 1.2, vil: [16, 24, 30, 34], army: [3, 9, 15, 22], firstWave: 780, waveGap: 330, waveBase: 5, waveGrow: 3, research: 0.8, towers: 2, wonderChance: 0.35, vilDefend: true },
  hard:   { think: 0.7, vil: [18, 27, 33, 38], army: [4, 11, 18, 26], firstWave: 600, waveGap: 270, waveBase: 6, waveGrow: 3, research: 1.0, towers: 3, wonderChance: 0.5, vilDefend: true },
};

const AI_TECH_PRIORITY = [
  'woodworking', 'domestication', 'goldmining', 'watchtower', 'toolworking', 'battleaxe', 'leatherarmor', 'stonemining',
  'wheel', 'plow', 'artisanship', 'metalworking', 'bronzeshield', 'astrology', 'architecture', 'mysticism', 'nobility',
  'sentrytower', 'wargalley', 'improvedfishing', 'writing', 'catapult', 'heavycavalry', 'phalanx', 'longsword', 'compositebow',
  'metallurgy', 'chainmail', 'irrigation', 'craftsmanship', 'alchemy', 'ballistics', 'engineering', 'afterlife', 'monotheism',
  'fanaticism', 'polytheism', 'aristocracy', 'scythechariot', 'trireme', 'guardtower', 'smallwall', 'mediumwall',
];

const AI_BASE_WEIGHTS = [
  [0.56, 0.44, 0.0, 0.0],
  [0.42, 0.36, 0.16, 0.06],
  [0.38, 0.30, 0.24, 0.08],
  [0.34, 0.28, 0.28, 0.10],
];

class AIController {
  constructor(game, p) {
    this.g = game; this.p = p;
    this.d = AI_DIFF[p.difficulty] || AI_DIFF.normal;
    this.timer = game.rng() * this.d.think;
    this.waveNum = 0; this.nextWave = this.d.firstWave * (0.9 + game.rng() * 0.2);
    this.wave = null;
    this.prefs = (p.civDef && p.civDef.ai && p.civDef.ai.prefer) || {};
    this.cool = {};
    this.wonderDecided = false; this.wonderPlan = false;
    this.alarm = null;
    this.dockSpotFail = -1000;
    const tc = game.buildings.find(b => b.owner === p.id && b.type === 'towncenter');
    this.home = tc ? { x: tc.x, y: tc.y } : { x: game.W * TILE / 2, y: game.H * TILE / 2 };
    this.waterNear = null;
  }
  update(dt) {
    this.timer -= dt;
    if (this.timer > 0) return;
    this.timer = this.d.think;
    if (!this.p.alive || this.g.over) return;
    this.think();
  }
  onAttacked(t, attacker) {
    if (attacker && attacker.kind === 'unit') this.alarm = { x: attacker.x, y: attacker.y, time: this.g.time, id: attacker.id };
  }
  ready(key, sec) {
    const t = this.cool[key] || -1e9;
    if (this.g.time - t < sec) return false;
    return true;
  }
  mark(key) { this.cool[key] = this.g.time; }

  /* ---------- survey ---------- */
  scan() {
    const g = this.g, p = this.p;
    this.vills = []; this.mil = []; this.priests = []; this.boats = []; this.warships = []; this.siege = [];
    for (const u of g.units) {
      if (u.dead || u.owner !== p.id) continue;
      const c = UNITS[u.type].cls;
      if (c === 'villager') this.vills.push(u);
      else if (c === 'fishing') this.boats.push(u);
      else if (c === 'ship') this.warships.push(u);
      else if (c === 'priest') this.priests.push(u);
      else if (c === 'siege') this.siege.push(u);
      else this.mil.push(u);
    }
    this.blds = {}; this.built = {}; this.found = [];
    this.myBuildings = [];
    for (const b of g.buildings) {
      if (b.dead || b.owner !== p.id) continue;
      (this.blds[b.type] || (this.blds[b.type] = [])).push(b);
      if (b.built) this.built[b.type] = (this.built[b.type] || 0) + 1; else this.found.push(b);
      if (b.type !== 'wall' && b.type !== 'farm') this.myBuildings.push(b);
    }
    this.tcs = (this.blds.towncenter || []).filter(b => b.built);
    this.dangerPts = g.buildings.filter(b => !b.dead && (b.type === 'towncenter' || b.type === 'tower') && g.isEnemy(p.id, b.owner));
    if (this.tcs.length) this.home = { x: this.tcs[0].x, y: this.tcs[0].y };
    this.queued = { villager: 0, units: 0, fishingboat: 0, ships: 0, priest: 0, siege: 0 };
    for (const b of g.buildings) {
      if (b.dead || b.owner !== p.id) continue;
      for (const q of b.queue) if (q.kind === 'unit') {
        const c = UNITS[q.key].cls;
        this.queued.units++;
        if (q.key === 'villager') this.queued.villager++;
        else if (q.key === 'fishingboat') this.queued.fishingboat++;
        else if (c === 'ship') this.queued.ships++;
        else if (c === 'priest') this.queued.priest++;
        else if (c === 'siege') this.queued.siege++;
      }
    }
    this.pending = t => (this.blds[t] || []).filter(b => !b.built).length;
    this.count = t => (this.blds[t] || []).length;
  }

  think() {
    this.scan();
    const p = this.p;
    if (!this.vills.length && !this.tcs.length) { this.defend(); this.waves(); return; }
    this.computeReserve();
    this.ensureBuilders();
    this.houses();
    this.trainVillagers();
    this.ageBuildings();
    this.ageUp();
    this.dropsites();
    this.assignVillagers();
    this.navy();
    this.militaryBuildings();
    this.towers();
    this.trainMilitary();
    this.research();
    this.wonder();
    this.defend();
    this.waves();
    void p;
  }

  /* ---------- spending discipline ---------- */
  computeReserve() {
    const g = this.g, p = this.p;
    this.reserve = null;
    const next = p.age + 1;
    if (next > 3) {
      if (this.wonderPlan && !this.count('wonder')) this.reserve = BUILDINGS.wonder.cost;
      return;
    }
    const st = g.ageReqStatus(p, next);
    const tech = AGE_REQ[next].tech;
    if (p.researching.has(tech)) return;
    if (st.ok && this.vills.length >= this.d.vil[p.age] * 0.75) this.reserve = TECHS[tech].cost;
  }
  canSpend(cost, prio) {
    const p = this.p;
    if (!p.canAfford(cost)) return false;
    if (prio === 'high' || !this.reserve) return true;
    const f = prio === 'mid' ? 0.5 : 1;
    for (const k in cost) if (cost[k] && p.res[k] - cost[k] < (this.reserve[k] || 0) * f) return false;
    return true;
  }

  /* ---------- placement ---------- */
  marginOK(type, tx, ty, margin) {
    if (!margin) return true;
    const g = this.g, s = BUILDINGS[type].size;
    for (let y = ty - margin; y < ty + s + margin; y++) for (let x = tx - margin; x < tx + s + margin; x++) {
      if (x >= tx && x < tx + s && y >= ty && y < ty + s) continue;
      if (!g.inside(x, y)) return false;
      const id = g.occ[y * g.W + x];
      if (id) { const e = g.ents.get(id); if (e && e.kind === 'building') return false; }
    }
    return true;
  }
  findSpot(type, cx, cy, rmin, rmax, margin) {
    const g = this.g, s = BUILDINGS[type].size;
    const ctx = Math.floor(cx / TILE - s / 2 + 0.5), cty = Math.floor(cy / TILE - s / 2 + 0.5);
    for (let r = rmin; r <= rmax; r++) {
      const cand = [];
      for (let y = cty - r; y <= cty + r; y++) for (let x = ctx - r; x <= ctx + r; x++) {
        if (Math.max(Math.abs(x - ctx), Math.abs(y - cty)) !== r) continue;
        cand.push([x, y]);
      }
      shuffle(cand, g.rng);
      for (const [x, y] of cand) {
        if (!g.canPlace(this.p.id, type, x, y, false).ok) continue;
        if (!this.marginOK(type, x, y, margin)) continue;
        // keep the town centre's surroundings walkable
        if (type !== 'farm' && this.tcs.length && Math.abs(x + s / 2 - this.home.x / TILE) < 3 + s / 2 && Math.abs(y + s / 2 - this.home.y / TILE) < 3 + s / 2) continue;
        return { x, y };
      }
    }
    return null;
  }
  placeAndBuild(type, cx, cy, rmin, rmax, margin, builders) {
    const g = this.g, p = this.p;
    const cost = p.bs(type).cost;
    if (!p.canAfford(cost)) return null;
    const spot = this.findSpot(type, cx, cy, rmin, rmax, margin);
    if (!spot) return null;
    const r = g.placeBuilding(p.id, type, spot.x, spot.y, false);
    if (!r.ok) return null;
    this.assignBuilders(r.building, builders || 1);
    return r.building;
  }
  pickVillager(x, y, exclude) {
    let best = null, bs = 1e9;
    for (const v of this.vills) {
      if (exclude && exclude.has(v.id)) continue;
      const o = v.order;
      if (o && (o.type === 'build' || (o.type === 'attack' && o.resume))) continue;
      let sc = Math.hypot(v.x - x, v.y - y);
      if (o && o.type === 'gather') {
        if (o.cat === 'farm') sc += 6 * TILE;
        if (o.cat === 'hunt') sc += 10 * TILE;
        if (o.cat === 'wood') sc -= 2 * TILE;
      }
      if (!o) sc -= 8 * TILE;
      if (sc < bs) { bs = sc; best = v; }
    }
    return best;
  }
  assignBuilders(b, n) {
    const ex = new Set();
    for (let i = 0; i < n; i++) {
      const v = this.pickVillager(b.x, b.y, ex);
      if (!v) break;
      ex.add(v.id);
      this.g.cmdBuild([v], b, true);
    }
  }
  ensureBuilders() {
    for (const b of this.found) {
      const want = BUILDINGS[b.type].wonder ? Math.min(14, Math.max(6, Math.floor(this.vills.length * 0.4))) : b.type === 'towncenter' ? 4 : 1;
      let have = 0;
      for (const v of this.vills) if (v.order && v.order.type === 'build' && v.order.target === b.id) have++;
      if (have < want) this.assignBuilders(b, want - have);
    }
  }

  /* ---------- economy ---------- */
  houses() {
    const g = this.g, p = this.p;
    if (p.popCap >= g.popLimit) return;
    const pend = this.pending('house');
    const room = p.popCap - p.pop - this.queued.units;
    const ahead = p.age === 0 ? 2 : p.pop > 30 ? 6 : 4;
    if (room <= ahead && pend < (p.pop > 24 ? 2 : 1) && p.res.wood >= 30) {
      const c = this.houseCenter();
      this.placeAndBuild('house', c.x, c.y, 3, 16, 1, 1);
    }
  }
  houseCenter() {
    // houses cluster on the side of town away from the nearest enemy
    const g = this.g;
    let ex = g.W * TILE / 2, ey = g.H * TILE / 2;
    const en = this.nearestEnemyBase();
    if (en) { ex = en.x; ey = en.y; }
    const a = Math.atan2(this.home.y - ey, this.home.x - ex);
    return { x: this.home.x + Math.cos(a) * 3 * TILE, y: this.home.y + Math.sin(a) * 3 * TILE };
  }
  nearestEnemyBase() {
    const g = this.g;
    let best = null, bd = 1e12;
    for (const b of g.buildings) {
      if (b.dead || !g.isEnemy(this.p.id, b.owner) || b.type === 'wall' || b.type === 'farm') continue;
      const d = Math.hypot(b.x - this.home.x, b.y - this.home.y) + (b.type === 'towncenter' ? -5 * TILE : 0);
      if (d < bd) { bd = d; best = b; }
    }
    return best;
  }
  trainVillagers() {
    const g = this.g, p = this.p;
    let target = this.d.vil[p.age];
    if (this.wonderPlan) target += 6;
    target = Math.min(target, Math.floor(g.popLimit * 0.58));
    const have = this.vills.length + this.queued.villager;
    if (have >= target) return;
    const cost = p.us('villager').cost;
    for (const tc of this.tcs) {
      if (tc.queue.length >= 2 || tc.queue.some(q => q.kind === 'tech')) continue;
      if (p.pop + this.queued.units >= p.popCap + 1) continue;
      if (!this.canSpend(cost, 'high')) return;
      if (g.queueTrain(tc, 'villager').ok) { this.queued.villager++; this.queued.units++; }
      if (this.vills.length + this.queued.villager >= target) return;
    }
  }
  ageBuildings() {
    const g = this.g, p = this.p;
    const next = p.age + 1;
    if (next > 3) return;
    const st = g.ageReqStatus(p, next);
    if (st.ok) return;
    const vThresh = [7, 13, 20][p.age];
    if (this.vills.length < vThresh) return;
    const missing = st.of.filter(k => !st.have.includes(k));
    if (missing.some(k => this.pending(k))) return;
    const order = {
      1: ['storagepit', 'granary', 'barracks', 'dock'],
      2: ['market', this.prefersArchers() ? 'archeryrange' : 'stable', this.prefersArchers() ? 'stable' : 'archeryrange'],
      3: [this.wantsTemple() ? 'temple' : 'siegeworkshop', this.wantsTemple() ? 'siegeworkshop' : 'temple', 'governmentcenter', 'academy'],
    }[next];
    for (const k of order) {
      if (!missing.includes(k) || this.count(k)) continue;
      if (!g.buildStatus(p, k).ok) continue;
      if (k === 'dock') continue; // handled by navy()
      if (k === 'storagepit' || k === 'granary') {
        if (this.placeDropsite(k)) return;
        if (!p.canAfford(p.bs(k).cost)) { this.saveFor(p.bs(k).cost); return; }
        continue;
      }
      if (this.placeAndBuild(k, this.home.x, this.home.y, 4, 16, 1, 2)) return;
      this.saveFor(p.bs(k).cost); // keep soldiers from eating the budget
      return;
    }
  }
  prefersArchers() {
    let a = 0, c = 0;
    for (const k in this.prefs) { const cls = UNITS[k] && UNITS[k].cls; if (cls === 'archer') a += this.prefs[k]; if (cls === 'cavalry') c += this.prefs[k]; }
    return a >= c;
  }
  wantsTemple() { return (this.prefs.priest || 0) >= 2 || this.p.civ === 'egyptians' || this.p.civ === 'babylonians'; }
  ageUp() {
    const g = this.g, p = this.p;
    const next = p.age + 1;
    if (next > 3 || !this.tcs.length) return;
    const key = AGE_REQ[next].tech;
    if (p.researching.has(key)) return;
    const st = g.techStatus(p, key);
    if (!st.ok) return;
    if (!p.canAfford(TECHS[key].cost)) return;
    const tc = this.tcs.slice().sort((a, b) => a.queue.length - b.queue.length)[0];
    if (tc.queue.length >= MAX_QUEUE) return;
    g.queueResearch(tc, key);
  }
  dropoffsFor(cat) {
    const out = [];
    for (const t in this.blds) for (const b of this.blds[t]) {
      if (!b.built && t !== 'storagepit' && t !== 'granary') continue;
      const dr = BUILDINGS[t].drop;
      if (dr && dr.includes(cat)) out.push(b);
    }
    return out;
  }
  placeDropsite(type) {
    const g = this.g, p = this.p;
    if (!this.ready('drop', 20)) return false;
    if (!this.canSpend(p.bs(type).cost, 'high')) return false;
    const cats = type === 'granary' ? ['forage'] : ['wood', 'gold', 'stone'];
    // choose the resource cluster near home that is furthest from an existing drop site
    let best = null, bs = 1e12;
    for (const r of g.resources) {
      if (r.dead || !cats.includes(RESOURCE_DEFS[r.type].cat)) continue;
      const dh = Math.hypot(r.x - this.home.x, r.y - this.home.y);
      if (dh > 22 * TILE) continue;
      let dd = 1e9;
      for (const b of this.dropoffsFor(RESOURCE_DEFS[r.type].cat)) dd = Math.min(dd, Math.hypot(b.x - r.x, b.y - r.y));
      if (dd < 7 * TILE) continue;
      const sc = dh + (RESOURCE_DEFS[r.type].cat === 'wood' ? -4 * TILE : 0);
      if (sc < bs) { bs = sc; best = r; }
    }
    const c = best || this.home;
    const b = this.placeAndBuild(type, c.x, c.y, best ? 2 : 4, best ? 6 : 12, 1, 1);
    if (b) { this.mark('drop'); return true; }
    return false;
  }
  dropsites() {
    const g = this.g;
    if (!this.ready('drop', 25)) return;
    for (const cat of ['wood', 'gold', 'stone', 'forage']) {
      let far = 0, n = 0, sx = 0, sy = 0;
      const drops = this.dropoffsFor(cat);
      for (const v of this.vills) {
        const o = v.order;
        if (!o || o.type !== 'gather' || o.cat !== cat) continue;
        const t = g.ents.get(o.target);
        if (!t || t.kind !== 'resource') continue;
        n++;
        let dd = 1e9;
        for (const b of drops) dd = Math.min(dd, g.distTo(t, b));
        if (dd > 6 * TILE) { far++; sx += t.x; sy += t.y; }
      }
      if (far >= 2 && far >= n * 0.4) {
        const type = cat === 'forage' ? 'granary' : 'storagepit';
        if (this.pending(type) || this.count(type) >= (type === 'granary' ? 2 : 5)) continue;
        if (!this.canSpend(this.p.bs(type).cost, 'high')) continue;
        const b = this.placeAndBuild(type, sx / far, sy / far, 2, 6, 1, 1);
        if (b) { this.mark('drop'); return; }
      }
    }
  }
  weights() {
    const p = this.p;
    let w = AI_BASE_WEIGHTS[p.age].slice();
    const next = p.age + 1;
    const nc = next <= 3 ? TECHS[AGE_REQ[next].tech].cost : {};
    // stockpile targets: what the AI expects to spend soon
    const want = {
      food: 250 + (nc.food || 0),
      wood: 250 + p.age * 100,
      gold: (p.age >= 1 ? 200 : 0) + (nc.gold || 0) + (p.age >= 2 ? 200 : 0),
      stone: p.age >= 1 ? 200 : 0,
    };
    if (this.wonderPlan && !this.wonderBuilt()) {
      w = [0.22, 0.3, 0.26, 0.22];
      for (const k of ['wood', 'gold', 'stone']) want[k] = 1100;
    }
    if (this.needStone()) w[3] = Math.max(w[3], 0.08);
    RES_KEYS.forEach((k, i) => {
      const ratio = p.res[k] / Math.max(1, want[k]);
      if (ratio > 1) w[i] *= Math.max(0.12, 1 / (ratio * ratio));
      else if (ratio < 0.3 && w[i] > 0) w[i] *= 1.3;
    });
    const s = w.reduce((a, b) => a + b, 0) || 1;
    return w.map(x => x / s);
  }
  saveFor(cost) {
    const r = Object.assign({}, this.reserve || {});
    for (const k in cost) r[k] = (r[k] || 0) + cost[k];
    this.reserve = r;
  }
  needStone() {
    const p = this.p;
    if (p.res.stone > 250) return false;
    return p.age >= 1 && (p.techs.has('watchtower') || p.age >= 2);
  }
  wonderBuilt() { return (this.blds.wonder || []).length > 0; }
  orderRes(v) {
    const o = v.order;
    if (!o || o.type !== 'gather') return null;
    if (o.cat) return CAT_RES[o.cat];
    const t = this.g.ents.get(o.target);
    if (!t) return null;
    if (t.kind === 'resource') return RESOURCE_DEFS[t.type].res;
    return 'food';
  }
  assignVillagers() {
    const g = this.g;
    const w = this.weights();
    const total = this.vills.length;
    const counts = { food: 0, wood: 0, gold: 0, stone: 0 };
    const by = { food: [], wood: [], gold: [], stone: [] };
    const idle = [];
    for (const v of this.vills) {
      const o = v.order;
      if (!o) { idle.push(v); continue; }
      const r = this.orderRes(v);
      if (r) { counts[r]++; by[r].push(v); }
      else if (o.type === 'move') idle.push(v);
    }
    const desired = {};
    RES_KEYS.forEach((k, i) => desired[k] = w[i] * total);
    for (const v of idle) {
      const order = RES_KEYS.slice().sort((a, b) => (desired[b] - counts[b]) - (desired[a] - counts[a]));
      for (const k of order) {
        if (this.assignTo(v, k)) { counts[k]++; break; }
      }
    }
    // gentle rebalancing: move one villager per think from the largest surplus to the largest deficit
    let def = null, sur = null, dv = 1.5, sv = 1.5;
    for (const k of RES_KEYS) {
      if (desired[k] - counts[k] > dv) { dv = desired[k] - counts[k]; def = k; }
      if (counts[k] - desired[k] > sv) { sv = counts[k] - desired[k]; sur = k; }
    }
    if (def && sur && this.ready('rebalance', 4)) {
      const cand = by[sur].filter(v => v.carry < 3 && v.order.cat !== 'hunt');
      if (cand.length) { if (this.assignTo(cand[0], def)) this.mark('rebalance'); }
    }
    void g;
  }
  assignTo(v, res) {
    if (res === 'food') return this.assignFood(v);
    const t = this.findRes(res, v);
    if (!t) return false;
    this.g.setOrder(v, { type: 'gather', target: t.id });
    return true;
  }
  findRes(cat, v) {
    const g = this.g;
    const drops = this.dropoffsFor(cat);
    if (!drops.length) drops.push({ x: this.home.x, y: this.home.y, kind: 'pt' });
    let best = null, bs = 1e12;
    for (const r of g.resources) {
      if (r.dead || r.amount <= 0 || RESOURCE_DEFS[r.type].cat !== cat) continue;
      if (r.unreach && r.unreach[this.p.id] && g.time - r.unreach[this.p.id] < 120) continue;
      const dh = Math.hypot(r.x - this.home.x, r.y - this.home.y);
      if (dh > 45 * TILE) continue;
      let dd = 1e9;
      for (const b of drops) dd = Math.min(dd, Math.hypot(b.x - r.x, b.y - r.y));
      const sc = dd + r.gc * 1.2 * TILE + Math.hypot(r.x - v.x, r.y - v.y) * 0.25 + this.dangerAt(r.x, r.y);
      if (sc < bs) { bs = sc; best = r; }
    }
    return best;
  }
  dangerAt(x, y) {
    // avoid gathering next to enemy towers or town centres
    let pen = 0;
    for (const b of this.dangerPts) if (Math.abs(b.x - x) < 12 * TILE && Math.abs(b.y - y) < 12 * TILE) pen += 30 * TILE;
    return pen;
  }
  assignFood(v) {
    const g = this.g, p = this.p;
    const drops = this.dropoffsFor('forage');
    const dropDist = (x, y) => { let d = 1e9; for (const b of drops) d = Math.min(d, Math.hypot(b.x - x, b.y - y)); return d; };
    const maxDrop = (p.age === 0 ? 16 : 9) * TILE;
    if (p.age >= 1) {
      const f = g.findFreeFarm(v, p, 40 * TILE);
      if (f) { g.setOrder(v, { type: 'gather', target: f.id }); return true; }
    }
    // carcass already on the ground
    let best = null, bs = 1e12;
    for (const r of g.resources) {
      if (r.dead || r.type !== 'carcass' || r.amount < 25 || r.gc >= 4) continue;
      const d = dropDist(r.x, r.y);
      if (d > maxDrop + 4 * TILE) continue;
      if (d + r.gc * TILE < bs) { bs = d + r.gc * TILE; best = r; }
    }
    if (best) { g.setOrder(v, { type: 'gather', target: best.id }); return true; }
    // live gazelles
    let hunters = 0;
    for (const u of this.vills) if (u.order && u.order.type === 'gather' && u.order.cat === 'hunt') hunters++;
    if (hunters < 6) {
      let ga = null, gd = 1e12;
      for (const u of g.units) {
        if (u.dead || u.owner !== 0 || u.type !== 'gazelle') continue;
        const d = dropDist(u.x, u.y);
        if (d > maxDrop || this.dangerAt(u.x, u.y) > 0) continue;
        if (d < gd) { gd = d; ga = u; }
      }
      if (ga) { g.setOrder(v, { type: 'gather', target: ga.id, cat: 'hunt' }); return true; }
    }
    // berry bushes close to a drop-off
    let bush = null; bs = 1e12;
    for (const r of g.resources) {
      if (r.dead || r.type !== 'bush' || r.gc >= 4) continue;
      const d = dropDist(r.x, r.y);
      if (d > maxDrop) continue;
      const sc = d + r.gc * TILE + Math.hypot(r.x - v.x, r.y - v.y) * 0.2;
      if (sc < bs) { bs = sc; bush = r; }
    }
    if (bush) { g.setOrder(v, { type: 'gather', target: bush.id }); return true; }
    // farms
    if (p.age >= 1 && g.buildStatus(p, 'farm').ok && this.canSpend(p.bs('farm').cost, 'mid')) {
      const anchors = (this.blds.granary || []).filter(b => b.built).concat(this.tcs);
      for (const a of anchors) {
        const spot = this.findSpot('farm', a.x, a.y, 2, 6, 0);
        if (!spot) continue;
        const r = g.placeBuilding(p.id, 'farm', spot.x, spot.y, false);
        if (r.ok) { g.setOrder(v, { type: 'build', target: r.building.id }); return true; }
      }
    }
    if (p.age >= 1 && g.buildStatus(p, 'farm').ok && p.res.food < 400) this.saveFor(p.bs('farm').cost);
    const far = g.findResource(this.home.x, this.home.y, ['forage', 'hunt'], 30 * TILE, p.id);
    if (far) { g.setOrder(v, { type: 'gather', target: far.id }); return true; }
    return false;
  }

  /* ---------- navy ---------- */
  navy() {
    const g = this.g, p = this.p;
    if (this.waterNear === null) {
      let fish = 0;
      for (const r of g.resources) if (r.type === 'fish' && Math.hypot(r.x - this.home.x, r.y - this.home.y) < 30 * TILE) fish++;
      this.waterNear = fish >= 2;
    }
    if (!this.waterNear) return;
    const docks = this.blds.dock || [];
    if (!docks.length && this.vills.length >= 9 && g.time - this.dockSpotFail > 120 && this.canSpend(p.bs('dock').cost, 'high')) {
      const spot = this.findDockSpot();
      if (spot) {
        const r = g.placeBuilding(p.id, 'dock', spot.x, spot.y, false);
        if (r.ok) this.assignBuilders(r.building, 1);
      } else this.dockSpotFail = g.time;
      return;
    }
    const built = docks.filter(b => b.built);
    if (!built.length) return;
    const dock = built[0];
    let fishNear = 0;
    for (const r of g.resources) if (r.type === 'fish' && !r.dead && Math.hypot(r.x - dock.x, r.y - dock.y) < 26 * TILE) fishNear++;
    const boatTarget = Math.min(5, fishNear * 2);
    if (this.boats.length + this.queued.fishingboat < boatTarget && dock.queue.length < 2 && p.pop + this.queued.units < p.popCap && this.canSpend(p.us('fishingboat').cost, 'mid')) {
      g.queueTrain(dock, 'fishingboat');
    }
    for (const b of this.boats) {
      if (b.order) continue;
      const f = g.findResource(dock.x, dock.y, ['fish'], 30 * TILE, p.id);
      if (f) g.setOrder(b, { type: 'gather', target: f.id });
    }
    // warships
    const shipTarget = [0, 2, 3, 5][p.age];
    if (p.age >= 1 && this.warships.length + this.queued.ships < shipTarget && dock.queue.length < 2 && p.pop + this.queued.units < p.popCap) {
      const key = p.age >= 3 && !p.disabled('cattrireme') && g.rng() < 0.4 ? 'cattrireme' : 'scoutship';
      if (g.unitStatus(p, key).ok && this.canSpend(p.us(p.resolve(key)).cost, 'low')) g.queueTrain(dock, key);
    }
    // naval raids against enemy docks and boats
    if (this.warships.length >= 3) {
      const idle = this.warships.filter(s => !s.order);
      if (idle.length >= 2) {
        let tgt = null, bd = 1e12;
        for (const b of g.buildings) if (!b.dead && b.type === 'dock' && g.isEnemy(p.id, b.owner)) { const d = Math.hypot(b.x - dock.x, b.y - dock.y); if (d < bd) { bd = d; tgt = b; } }
        if (!tgt) for (const u of g.units) if (!u.dead && UNITS[u.type].naval && g.isEnemy(p.id, u.owner)) { const d = Math.hypot(u.x - dock.x, u.y - dock.y); if (d < bd) { bd = d; tgt = u; } }
        if (tgt) g.cmdMove(idle, tgt.x, tgt.y, true);
      }
    }
  }
  findDockSpot() {
    const g = this.g;
    const hx = Math.floor(this.home.x / TILE), hy = Math.floor(this.home.y / TILE);
    let best = null, bd = 1e9;
    for (let y = hy - 24; y <= hy + 24; y++) for (let x = hx - 24; x <= hx + 24; x++) {
      if (!g.inside(x, y) || g.terrain[y * g.W + x] !== T_WATER) continue;
      const d = Math.hypot(x - hx, y - hy);
      if (d >= bd) continue;
      if (!g.canPlace(this.p.id, 'dock', x, y, false).ok) continue;
      bd = d; best = { x, y };
    }
    return best;
  }

  /* ---------- military ---------- */
  militaryBuildings() {
    const g = this.g, p = this.p;
    if (this.pendingMil()) return;
    const want = [];
    if (this.vills.length >= 9) want.push('barracks');
