    if (tx < 0 || ty < 0 || tx + s > this.W || ty + s > this.H) return { ok: false, reason: 'Outside the map' };
    for (let y = ty; y < ty + s; y++) for (let x = tx; x < tx + s; x++) {
      const i = y * W + x;
      if (this.occ[i] || this.soft[i]) return { ok: false, reason: 'Blocked' };
      if (checkFog && p.explored && !p.explored[i]) return { ok: false, reason: 'Unexplored' };
      const t = this.terrain[i];
      if (d.water ? t !== T_WATER : t === T_WATER) return { ok: false, reason: d.water ? 'Docks must be built in water next to the shore' : 'Cannot build on water' };
    }
    if (d.water) {
      let land = 0, water = 0;
      for (let y = ty - 1; y <= ty + s; y++) for (let x = tx - 1; x <= tx + s; x++) {
        if (x >= tx && x < tx + s && y >= ty && y < ty + s) continue;
        if (!this.inside(x, y)) continue;
        if (this.terrain[y * W + x] === T_WATER) { if (!this.occ[y * W + x]) water++; } else if (!this.occ[y * W + x]) land++;
      }
      if (land < 2 || water < 3) return { ok: false, reason: 'Docks must touch both shore and open water' };
    }
    // keep enemy units off the footprint
    const units = this.unitsNear((tx + s / 2) * TILE, (ty + s / 2) * TILE, s * TILE * 0.75);
    for (const u of units) if (this.isEnemy(pid, u.owner)) return { ok: false, reason: 'Enemy units in the way' };
    return { ok: true };
  }

  /* ---------- commands (used by UI and AI) ---------- */
  setOrder(u, o) { u.order = o; u.path = null; u.pathKey = null; u.fails = 0; u.stuckT = 0; }
  placeBuilding(pid, type, tx, ty, checkFog) {
    const p = this.players[pid];
    const st = this.buildStatus(p, type);
    if (!st.ok) return { ok: false, reason: st.reason };
    const pl = this.canPlace(pid, type, tx, ty, checkFog);
    if (!pl.ok) return pl;
    const cost = p.bs(type).cost;
    if (!p.canAfford(cost)) return { ok: false, reason: 'Not enough resources' };
    p.pay(cost);
    const b = this.spawnBuilding(type, pid, tx, ty, false);
    this.pushUnitsOut(b);
    if (BUILDINGS[type].wonder) {
      this.msg('all', '⚠ ' + p.name + ' of the ' + p.civName + ' has begun building a WONDER! Destroy it before it is completed and stands for ' + fmtTime(this.opts.wonderTime) + '.', 'wonder', b.x, b.y);
      this.sound('all', 'wonder');
      for (const q of this.players) if (q.explored) this.revealArea(q, b.tx + 2, b.ty + 2, 7);
    }
    return { ok: true, building: b };
  }
  wallTiles(tx0, ty0, tx1, ty1) {
    const out = [];
    let x = tx0, y = ty0;
    const dx = Math.abs(tx1 - tx0), dy = Math.abs(ty1 - ty0), sx = tx0 < tx1 ? 1 : -1, sy = ty0 < ty1 ? 1 : -1;
    let err = dx - dy;
    out.push([x, y]);
    let guard = 0;
    while ((x !== tx1 || y !== ty1) && guard++ < 400) {
      const e2 = 2 * err;
      // 4-connected line so diagonal walls have no gaps
      if (e2 > -dy && (Math.abs(e2 + dy) <= Math.abs(e2 - dx) || e2 >= dx)) { err -= dy; x += sx; }
      else { err += dx; y += sy; }
      out.push([x, y]);
    }
    return out;
  }
  placeWall(pid, tx0, ty0, tx1, ty1, checkFog) {
    const placed = [];
    const p = this.players[pid];
    const st = this.buildStatus(p, 'wall');
    if (!st.ok) return { ok: false, reason: st.reason, placed };
    for (const [x, y] of this.wallTiles(tx0, ty0, tx1, ty1)) {
      if (!this.canPlace(pid, 'wall', x, y, checkFog).ok) continue;
      if (!p.canAfford(p.bs('wall').cost)) break;
      const r = this.placeBuilding(pid, 'wall', x, y, checkFog);
      if (r.ok) placed.push(r.building);
    }
    return { ok: placed.length > 0, placed, reason: placed.length ? '' : 'Cannot place wall here' };
  }
  pushUnitsOut(b) {
    if (b.walkable) return;
    for (const u of this.unitsNear(b.x, b.y, b.size * TILE)) {
      const tx = Math.floor(u.x / TILE), ty = Math.floor(u.y / TILE);
      if (tx >= b.tx && ty >= b.ty && tx < b.tx + b.size && ty < b.ty + b.size) {
        const np = this.findNearestPassable(tx, ty, !!UNITS[u.type].naval, b.size + 3);
        if (np) { u.x = (np.x + 0.5) * TILE; u.y = (np.y + 0.5) * TILE; u.path = null; }
      }
    }
  }
  queueTrain(b, base) {
    const p = this.players[b.owner];
    if (!b.built) return { ok: false, reason: 'Building not complete' };
    if (!(BUILDINGS[b.type].trains || []).includes(base)) return { ok: false, reason: 'Cannot train here' };
    const st = this.unitStatus(p, base);
    if (!st.ok) return st;
    if (b.queue.length >= MAX_QUEUE) return { ok: false, reason: 'Queue is full' };
    const key = p.resolve(base);
    const cost = Object.assign({}, p.us(key).cost);
    if (!p.canAfford(cost)) return { ok: false, reason: 'Not enough resources' };
    p.pay(cost);
    b.queue.push({ kind: 'unit', key: base, progress: 0, cost, time: UNITS[key].time });
    return { ok: true };
  }
  queueResearch(b, key) {
    const p = this.players[b.owner];
    if (!b.built) return { ok: false, reason: 'Building not complete' };
    const st = this.techStatus(p, key);
    if (!st.ok) return { ok: false, reason: st.reason };
    if (b.queue.length >= MAX_QUEUE) return { ok: false, reason: 'Queue is full' };
    const t = TECHS[key];
    if (!p.canAfford(t.cost)) return { ok: false, reason: 'Not enough resources' };
    p.pay(t.cost);
    p.researching.add(key);
    b.queue.push({ kind: 'tech', key, progress: 0, cost: Object.assign({}, t.cost), time: t.time });
    if (t.advance) this.msg(b.owner, p.name + ' begins advancing to the ' + AGE_NAMES[t.advance] + '.', 'age');
    return { ok: true };
  }
  cancelQueue(b, idx) {
    const q = b.queue[idx];
    if (!q) return;
    const p = this.players[b.owner];
    p.refund(q.cost);
    if (q.kind === 'tech') p.researching.delete(q.key);
    b.queue.splice(idx, 1);
  }
  setRally(b, x, y, targetId) { b.rally = { x, y, target: targetId || 0 }; }
  deleteEntity(e) {
    if (!e || e.dead) return;
    if (e.kind === 'building') { for (let i = e.queue.length - 1; i >= 0; i--) this.cancelQueue(e, i); }
    this.kill(e, e.owner, 0);
  }
  cmdStop(units) { for (const u of units) this.setOrder(u, null); }
  cmdMove(units, x, y, attackMove) {
    const land = units.filter(u => !UNITS[u.type].naval), sea = units.filter(u => UNITS[u.type].naval);
    for (const group of [land, sea]) {
      const n = group.length; if (!n) continue;
      const naval = group === sea;
      const cols = Math.ceil(Math.sqrt(n)), rows = Math.ceil(n / cols);
      const sp = naval ? 36 : 22;
      // sort so units fill nearest slots
      const cx = group.reduce((a, u) => a + u.x, 0) / n, cy = group.reduce((a, u) => a + u.y, 0) / n;
      const ang = Math.atan2(y - cy, x - cx);
      const fx = Math.cos(ang), fy = Math.sin(ang);
      const slots = [];
      for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
        const lx = (c - (cols - 1) / 2) * sp, ly = (r - (rows - 1) / 2) * sp;
        slots.push({ x: x + lx * -fy + ly * -fx, y: y + lx * fx + ly * -fy });
      }
      const sorted = group.slice().sort((a, b) => ((a.x - cx) * fx + (a.y - cy) * fy) - ((b.x - cx) * fx + (b.y - cy) * fy)).reverse();
      sorted.forEach((u, i) => {
        let s = slots[i] || { x, y };
        if (n === 1) s = { x, y };
        if (!this.passablePx(s.x, s.y, naval)) {
          const np = this.findNearestPassable(Math.floor(s.x / TILE), Math.floor(s.y / TILE), naval, 8);
          s = np ? { x: (np.x + 0.5) * TILE, y: (np.y + 0.5) * TILE } : { x, y };
        }
        this.setOrder(u, { type: attackMove ? 'attackMove' : 'move', x: s.x, y: s.y });
      });
    }
  }
  cmdAttack(units, t) { for (const u of units) if (this.us(u).atk > 0 || u.type === 'villager') this.setOrder(u, { type: 'attack', target: t.id, force: true }); }
  cmdGather(units, t) {
    for (const u of units) {
      if (t.kind === 'resource' && t.type === 'fish') { if (u.type === 'fishingboat') this.setOrder(u, { type: 'gather', target: t.id }); continue; }
      if (u.type !== 'villager') continue;
      this.setOrder(u, { type: 'gather', target: t.id });
    }
  }
  cmdBuild(units, b, resume) {
    for (const u of units) if (u.type === 'villager') this.setOrder(u, { type: 'build', target: b.id, resume: resume ? (u.order && u.order.type === 'gather' ? { type: 'gather', target: u.order.target } : null) : null });
  }
  cmdConvert(units, t) { for (const u of units) if (UNITS[u.type].cls === 'priest') this.setOrder(u, { type: 'convert', target: t.id, chan: 0, need: 0 }); }
  cmdHeal(units, t) { for (const u of units) if (UNITS[u.type].cls === 'priest') this.setOrder(u, { type: 'heal', target: t.id }); }
  /* context-sensitive right click */
  cmdSmart(units, x, y, t) {
    const movers = [];
    for (const u of units) {
      const d = UNITS[u.type];
      let done = false;
      if (t && !t.dead) {
        if (t.kind === 'resource') {
          if ((u.type === 'villager' && t.type !== 'fish') || (u.type === 'fishingboat' && t.type === 'fish')) { this.setOrder(u, { type: 'gather', target: t.id }); done = true; }
        } else if (t.kind === 'unit' && t.owner === 0 && UNITS[t.type].animal) {
          if (u.type === 'villager') { this.setOrder(u, { type: 'gather', target: t.id }); done = true; }
          else if (this.us(u).atk > 0) { this.setOrder(u, { type: 'attack', target: t.id, force: true }); done = true; }
        } else if (t.owner === u.owner || this.allied(t.owner, u.owner)) {
          if (t.kind === 'building' && t.owner === u.owner) {
            if (u.type === 'villager') {
              if (!t.built || t.hp < t.maxHp) { this.setOrder(u, { type: 'build', target: t.id }); done = true; }
              else if (t.type === 'farm') { this.setOrder(u, { type: 'gather', target: t.id }); done = true; }
              else if (u.carry > 0 && BUILDINGS[t.type].drop && BUILDINGS[t.type].drop.includes(u.carryCat)) { this.setOrder(u, { type: 'gather', target: u.lastRes || 0, state: 'return', drop: t.id }); done = true; }
            } else if (u.type === 'fishingboat' && t.type === 'dock' && u.carry > 0) { this.setOrder(u, { type: 'gather', target: u.lastRes || 0, state: 'return', drop: t.id }); done = true; }
          } else if (t.kind === 'unit' && d.cls === 'priest' && t.hp < t.maxHp) { this.setOrder(u, { type: 'heal', target: t.id }); done = true; }
        } else if (this.isEnemy(u.owner, t.owner)) {
          if (d.cls === 'priest') { this.setOrder(u, { type: 'convert', target: t.id, chan: 0, need: 0 }); done = true; }
          else if (this.us(u).atk > 0) { this.setOrder(u, { type: 'attack', target: t.id, force: true }); done = true; }
        }
      }
      if (!done) movers.push(u);
    }
    if (movers.length) this.cmdMove(movers, x, y, false);
  }

  /* ---------- main step ---------- */
  step() {
    const dt = SIM_DT;
    this.time += dt; this.tickN++;
    this.pathBudget = 20000;
    for (const ai of this.ais) ai.update(dt);
    this.rebuildHash();
    for (const b of this.buildings) if (!b.built) { b.nb = b.nbc; b.nbc = 0; }
    const units = this.units;
    for (let i = 0; i < units.length; i++) { const u = units[i]; if (!u.dead) this.updateUnit(u, dt); }
    this.separate();
    for (const b of this.buildings) if (!b.dead) this.updateBuilding(b, dt);
    this.updateProjectiles(dt);
    this.updateResources(dt);
    this.updateFx(dt);
    this.cleanup();
    this.updatePop();
    if (this.tickN % 4 === 0) this.updateVisibility();
    if (this.tickN % 10 === 0) this.recountGatherers();
    if (this.tickN % 20 === 0) this.checkVictory();
  }

  cleanup() {
    if (this.units.some(u => u.dead)) {
      this.units = this.units.filter(u => { if (u.dead) { this.ents.delete(u.id); return false; } return true; });
    }
    if (this.buildings.some(b => b.dead)) {
      this.buildings = this.buildings.filter(b => { if (b.dead) { this.ents.delete(b.id); return false; } return true; });
    }
    if (this.resources.some(r => r.dead)) {
      this.resources = this.resources.filter(r => { if (r.dead) { this.ents.delete(r.id); return false; } return true; });
    }
    if (this.carcassOf.size > 200) {
      for (const [k, v] of this.carcassOf) if (!this.ents.has(v)) this.carcassOf.delete(k);
    }
  }
  updatePop() {
    for (const p of this.players) { p.pop = 0; p.capRaw = 0; }
    for (const u of this.units) if (!u.dead && u.owner) this.players[u.owner].pop++;
    for (const b of this.buildings) if (!b.dead && b.built) { const pp = BUILDINGS[b.type].pop; if (pp) this.players[b.owner].capRaw += pp; }
    for (const p of this.players) p.popCap = Math.min(this.popLimit, p.capRaw);
  }
  recountGatherers() {
    for (const r of this.resources) r.gc = 0;
    for (const u of this.units) {
      if (u.dead || !u.order || u.order.type !== 'gather') continue;
      const r = this.ents.get(u.order.target);
      if (r && r.kind === 'resource') r.gc++;
    }
  }

  /* ---------- units ---------- */
  updateUnit(u, dt) {
    const p = this.players[u.owner];
    const s = p.us(u.type);
    if (u.cool > 0) u.cool -= dt;
    if (u.anim > 0) u.anim -= dt;
    if (s.cls === 'priest' && u.faith < 100) u.faith = Math.min(100, u.faith + dt * (100 / 30) * p.eco.faithRegen);
    u.moving = false; u.working = false;
    const o = u.order;
    if (!o) this.idle(u, s, p, dt);
    else {
      switch (o.type) {
        case 'move': {
          const r = this.approach(u, s, dt, { x: o.x, y: o.y }, 3);
          if (r === 'arrived' || r === 'fail') u.order = null;
          break;
        }
        case 'attackMove': this.doAttackMove(u, s, p, dt, o); break;
        case 'attack': this.doAttack(u, s, p, dt, o); break;
        case 'gather': this.doGather(u, s, p, dt, o); break;
        case 'build': this.doBuild(u, s, p, dt, o); break;
        case 'convert': this.doConvert(u, s, p, dt, o); break;
        case 'heal': this.doHeal(u, s, p, dt, o); break;
        case 'flee': this.doFlee(u, s, dt, o); break;
        default: u.order = null;
      }
    }
    if (u.moving) u.walk += dt * s.speed * 7;
  }
  spd(u, s) { return s.speed * TILE * (u.order && u.order.wander ? 0.45 : 1); }

  approach(u, s, dt, target, reach) {
    const isEnt = !!target.kind;
    const d = isEnt ? this.distTo(u, target) : Math.hypot(target.x - u.x, target.y - u.y);
    if (d <= reach) { u.path = null; return 'arrived'; }
    const key = isEnt ? target.id : (Math.round(target.x) + ',' + Math.round(target.y));
    if (u.pathKey !== key) { u.path = null; u.pathKey = key; u.fails = 0; u.stuckT = 0; u.lastX = u.x; u.lastY = u.y; }
    if (isEnt && target.kind === 'unit' && u.path && this.time > u.repathAt) {
      if (Math.abs(target.x - u.ptx) + Math.abs(target.y - u.pty) > 1.5 * TILE || u.pi >= u.path.length) u.path = null;
      else u.repathAt = this.time + 0.8;
    }
    if (!u.path) {
      if (this.pathBudget <= 0) return 'wait';
      if (this.makePath(u, target, isEnt) === 'unreachable') return 'fail';
    }
    u.moving = true;
    const sp = this.spd(u, s) * dt;
    if (u.pi < u.path.length) {
      const wp = u.path[u.pi];
      if (this.stepToward(u, wp.x, wp.y, sp)) u.pi++;
    } else {
      let ax, ay;
      if (isEnt) { const np = this.nearestPoint(u, target); ax = np.x; ay = np.y; } else { ax = target.x; ay = target.y; }
      if (this.stepToward(u, ax, ay, sp) && !isEnt) return 'arrived';
    }
    u.stuckT += dt;
    if (u.stuckT >= 1) {
      const m = Math.hypot(u.x - u.lastX, u.y - u.lastY);
      u.lastX = u.x; u.lastY = u.y; u.stuckT = 0;
      if (m < this.spd(u, s) * 0.3) {
        u.fails++; u.path = null;
        if (u.fails >= 4) return 'fail';
      } else if (u.fails > 0 && m > this.spd(u, s) * 0.6) u.fails = Math.max(0, u.fails - 1);
    }
    return 'moving';
  }
  makePath(u, target, isEnt) {
    const naval = !!UNITS[u.type].naval;
    const sx = Math.floor(u.x / TILE), sy = Math.floor(u.y / TILE);
    let goal, endPoint = null, aim;
    if (isEnt) {
      if (target.kind === 'unit') {
        const tx = Math.floor(target.x / TILE), ty = Math.floor(target.y / TILE);
        goal = { x0: tx, y0: ty, x1: tx, y1: ty, inside: this.passable(tx, ty, naval) };
        aim = { x: target.x, y: target.y };
      } else {
        const sz = target.size || 1;
        goal = { x0: target.tx, y0: target.ty, x1: target.tx + sz - 1, y1: target.ty + sz - 1, inside: !!target.walkable };
        const np = this.nearestPoint(u, target);
        const L = Math.hypot(u.x - np.x, u.y - np.y) || 1;
        aim = target.walkable ? { x: target.x, y: target.y } : { x: np.x + (u.x - np.x) / L * 6, y: np.y + (u.y - np.y) / L * 6 };
      }
    } else {
      let tx = Math.floor(target.x / TILE), ty = Math.floor(target.y / TILE);
      if (this.passable(tx, ty, naval)) { endPoint = target; goal = { x0: tx, y0: ty, x1: tx, y1: ty, inside: true }; }
      else {
        const np = this.findNearestPassable(tx, ty, naval, 6);
        if (np) { tx = np.x; ty = np.y; goal = { x0: tx, y0: ty, x1: tx, y1: ty, inside: true }; }
        else goal = { x0: tx, y0: ty, x1: tx, y1: ty, inside: false };
      }
      aim = target;
    }
    const dd = Math.hypot(aim.x - u.x, aim.y - u.y);
    if (dd < 7 * TILE && this.pf.lineClear(u.x, u.y, aim.x, aim.y, naval, u.radius * 0.5)) {
      u.path = []; u.pi = 0; u.pathReached = true;
      u.ptx = aim.x; u.pty = aim.y;
      u.repathAt = this.time + 0.6;
      return;
    }
    u.ptx = aim.x; u.pty = aim.y;
    const res = this.pf.find(sx, sy, goal, naval, isEnt && target.kind === 'unit' ? 2500 : 5000);
    this.pathBudget -= res.nodes + 50;
    if (res.exhausted && !res.tiles.length) { u.path = []; u.pi = 0; return 'unreachable'; }
    u.path = this.pf.smooth(u.x, u.y, res.tiles, naval, u.radius * 0.5, endPoint && res.reached ? endPoint : null);
    u.pi = 0; u.pathReached = res.reached;
    u.repathAt = this.time + (isEnt && target.kind === 'unit' ? 1.2 : 1e9);
  }
  stepToward(u, ax, ay, sp) {
    const dx = ax - u.x, dy = ay - u.y, L = Math.hypot(dx, dy);
    if (L < 0.5) return true;
    const m = Math.min(sp, L);
    const nx = u.x + dx / L * m, ny = u.y + dy / L * m;
    u.dir = Math.atan2(dy, dx);
    const naval = !!UNITS[u.type].naval;
    const stuckNow = !this.passablePx(u.x, u.y, naval);
    if (stuckNow || this.passablePx(nx, ny, naval)) { u.x = nx; u.y = ny; }
    else if (Math.abs(dx) > 0.1 && this.passablePx(nx, u.y, naval)) u.x = nx;
    else if (Math.abs(dy) > 0.1 && this.passablePx(u.x, ny, naval)) u.y = ny;
    else return false;
    return m >= L - 0.01;
  }
  separate() {
    for (const u of this.units) {
      if (u.dead) continue;
      const near = this.unitsNear(u.x, u.y, u.radius + 18);
      for (const v of near) {
        if (v.id <= u.id) continue;
        const nu = !!UNITS[u.type].naval, nv = !!UNITS[v.type].naval;
        if (nu !== nv) continue;
        let dx = v.x - u.x, dy = v.y - u.y;
        let d = Math.hypot(dx, dy);
        const min = (u.radius + v.radius) * 0.85;
        if (d >= min) continue;
        if (d < 0.01) { dx = this.rng() - 0.5; dy = this.rng() - 0.5; d = Math.hypot(dx, dy); }
        const push = (min - d) * 0.35;
        const ux = dx / d * push, uy = dy / d * push;
        const wu = u.working ? 0.2 : (u.moving ? 0.6 : 1), wv = v.working ? 0.2 : (v.moving ? 0.6 : 1);
        const tw = wu + wv;
        const ax = u.x - ux * wu / tw * 2, ay = u.y - uy * wu / tw * 2;
        const bx = v.x + ux * wv / tw * 2, by = v.y + uy * wv / tw * 2;
        if (this.passablePx(ax, ay, nu)) { u.x = ax; u.y = ay; }
        if (this.passablePx(bx, by, nv)) { v.x = bx; v.y = by; }
      }
    }
  }

  idle(u, s, p, dt) {
    const d = UNITS[u.type];
    if (d.animal) return this.animalIdle(u, s, dt);
    u.scanT -= dt;
    if (u.scanT > 0) return;
    u.scanT = 0.5 + this.rng() * 0.25;
