  move(e) {
    this.mx = e.clientX; this.my = e.clientY;
    const ui = this.ui;
    if (e.target === this.cv) this.inside = true;
    const w = this.world();
    if (ui.placing) ui.updatePlacement(w.x, w.y);
    if (ui.drag) {
      ui.drag.cx = e.clientX; ui.drag.cy = e.clientY;
      if (Math.abs(ui.drag.cx - ui.drag.sx) + Math.abs(ui.drag.cy - ui.drag.sy) > 6) ui.drag.box = true;
    }
    if (this.mmDrag) this.mmMove(e);
    this.updateCursor(w);
  }
  up(e) {
    const ui = this.ui;
    if (this.mmDrag && e.button === 0) { this.mmDrag = false; return; }
    if (e.button !== 0) return;
    if (ui.placing && ui.placing.wallLine) { ui.finishWall(e.shiftKey); return; }
    if (!ui.drag) return;
    const d = ui.drag; ui.drag = null;
    const w = this.r.screenToWorld(e.clientX, e.clientY);
    if (d.box) ui.boxSelect(d.w0, w, e.shiftKey);
    else {
      const now = performance.now();
      const dbl = now - this.lastClick.t < 320 && Math.abs(this.lastClick.x - e.clientX) < 6 && Math.abs(this.lastClick.y - e.clientY) < 6;
      this.lastClick = { t: now, x: e.clientX, y: e.clientY };
      ui.clickSelect(w.x, w.y, e.shiftKey, dbl);
    }
  }
  wheel(e) {
    e.preventDefault();
    const r = this.r;
    const before = r.screenToWorld(e.clientX, e.clientY);
    r.cam.zoom = clamp(r.cam.zoom * (e.deltaY < 0 ? 1.12 : 1 / 1.12), 0.45, 1.8);
    r.cam.x = before.x - e.clientX / r.cam.zoom;
    r.cam.y = before.y - e.clientY / r.cam.zoom;
    r.clampCam();
  }
  updateCursor(w) {
    const ui = this.ui;
    let cur = 'default';
    if (ui.placing) cur = 'crosshair';
    else if (ui.mode === 'attackMove') cur = 'crosshair';
    else if (ui.sel.length && this.inside) {
      const t = ui.pickAt(w.x, w.y);
      const mine = ui.myUnits();
      if (t && mine.length) {
        if (ui.g.isEnemy(ui.pid, t.owner)) cur = 'crosshair';
        else if (t.kind === 'resource' || (t.kind === 'unit' && t.owner === 0)) cur = 'pointer';
        else if (t.kind === 'building' && t.owner === ui.pid && (!t.built || t.hp < t.maxHp)) cur = 'cell';
      }
    }
    if (cur !== this.cur) { this.cur = cur; this.cv.style.cursor = cur; }
  }
  mmToWorld(e) {
    const rect = this.mm.getBoundingClientRect();
    const g = this.ui.g;
    return { x: (e.clientX - rect.left) / rect.width * g.W * TILE, y: (e.clientY - rect.top) / rect.height * g.H * TILE };
  }
  mmDown(e) {
    e.preventDefault();
    const w = this.mmToWorld(e);
    if (e.button === 0) { this.mmDrag = true; this.r.centerOn(w.x, w.y); }
    else if (e.button === 2) {
      const units = this.ui.myUnits();
      if (units.length) { this.ui.g.cmdSmart(units, w.x, w.y, null); Sound.play('click'); }
    }
  }
  mmMove(e) { const w = this.mmToWorld(e); this.r.centerOn(w.x, w.y); }
  keydown(e) {
    const ui = this.ui, app = this.app;
    if (app.overlayOpen()) {
      if (e.key === 'Escape' || e.key === 'F10' || e.key === 'p' || e.key === 'P') { app.closeOverlays(); e.preventDefault(); }
      return;
    }
    if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT')) return;
    const k = e.key;
    if (k.startsWith('Arrow')) { this.keys.add(k); e.preventDefault(); return; }
    if (k === 'Escape') { if (ui.placing || ui.mode) { ui.placing = null; ui.mode = null; } else if (ui.page) { ui.page = null; ui.cmdSig = ''; } else ui.setSel([]); return; }
    if (k === 'F10' || k === 'p' && !e.ctrlKey && !this.isCmdKey('P') || k === 'Pause') { app.togglePause(true); e.preventDefault(); return; }
    if (k === 'F1') { app.showHelp(); e.preventDefault(); return; }
    if (k === 'Tab') { ui.scoreVisible = !ui.scoreVisible; e.preventDefault(); return; }
    if (k === 'Delete') { for (const en of ui.selEnts()) if (en.owner === ui.pid && en.type !== 'towncenter') ui.g.deleteEntity(en); return; }
    if (k === '.' || k === ',') { ui.nextIdle(); return; }
    if (k === ' ') { if (ui.lastAlert) this.r.centerOn(ui.lastAlert.x, ui.lastAlert.y); e.preventDefault(); return; }
    if (k === '+' || k === '=') { app.cycleSpeed(1); return; }
    if (k === '-' || k === '_') { app.cycleSpeed(-1); return; }
    if (/^[0-9]$/.test(k)) { ui.group(+k, e.ctrlKey || e.metaKey); e.preventDefault(); return; }
    const up = k.toUpperCase();
    if (up === 'H' && !ui.sel.length) { ui.selectTC(); return; }
    const idx = HOTKEYS.indexOf(up);
    if (idx >= 0 && up.length === 1) {
      ui.renderCommands();
      if (ui.cmdList && ui.cmdList[idx]) { ui.runCommand(idx, e.shiftKey); e.preventDefault(); return; }
      if (up === 'H') { ui.selectTC(); return; }
    }
  }
  isCmdKey(up) { const idx = HOTKEYS.indexOf(up); return idx >= 0 && this.ui.cmdList && this.ui.cmdList[idx]; }
  update(dt) {
    const r = this.r;
    const sp = 900 * dt / r.cam.zoom;
    let dx = 0, dy = 0;
    if (this.keys.has('ArrowLeft')) dx -= sp;
    if (this.keys.has('ArrowRight')) dx += sp;
    if (this.keys.has('ArrowUp')) dy -= sp;
    if (this.keys.has('ArrowDown')) dy += sp;
    if (this.inside && !this.ui.drag && document.hasFocus()) {
      const m = 8;
      if (this.mx >= 0 && this.mx < m) dx -= sp;
      if (this.mx > r.vw - m) dx += sp;
      if (this.my >= 0 && this.my < 4) dy -= sp;
      if (this.my > r.vh - 4) dy += sp;
    }
    if (dx || dy) { r.cam.x += dx; r.cam.y += dy; r.clampCam(); }
  }
}
"},{"path":"js/main.js","type":"text/javascript","text":"'use strict';
/* Application shell: setup menu, game lifecycle, main loop and overlays. */

const App = {
  speed: 1.5,
  speeds: [0.5, 1, 1.5, 2, 3, 4],
  game: null, ui: null, renderer: null, input: null,
  paused: false, running: false,
  lastOpts: null,

  init() {
    const st = document.createElement('style');
    st.textContent = ['food', 'wood', 'gold', 'stone', 'pop'].map(k => `.ri-${k}{background-image:url(${Sprites.glyphIcon(k, 40, 'none')})}`).join('\n');
    document.head.appendChild(st);
    this.buildMenu();
    window.addEventListener('resize', () => this.resize());
    this.loopFn = (t) => this.frame(t);
    // quick start via URL hash, e.g. index.html#quick&civ=greeks&opp=2&map=coastal&ff=300&spectate
    const h = location.hash.slice(1);
    if (h.startsWith('quick')) {
      const q = {};
      for (const part of h.split('&')) { const [k, v] = part.split('='); q[k] = v === undefined ? true : decodeURIComponent(v); }
      const civ = CIVS[q.civ] ? q.civ : 'egyptians';
      const n = +q.opp || 2;
      const players = q.spectate ? [] : [{ civ, human: true, name: 'You' }];
      const pool = CIV_KEYS.filter(k => k !== civ);
      for (let i = 0; i < (q.spectate ? Math.max(2, n) : n); i++) players.push({ civ: pool[i % pool.length], ai: true, difficulty: q.diff || 'normal', name: CIVS[pool[i % pool.length]].leader });
      this.start({ seed: +q.seed || 1234, mapType: q.map || 'inland', mapSize: q.size || 'medium', startRes: q.res || 'low', popLimit: 75, wonderTime: 360,
        teams: 'ffa', reveal: !!q.reveal, observer: !!q.spectate, players, fastForward: +q.ff || 0, zoom: +q.zoom || 1 });
    }
  },

  /* ---------- menu ---------- */
  buildMenu() {
    const civSel = document.getElementById('civ-cards');
    this.myCiv = 'egyptians';
    civSel.innerHTML = CIV_KEYS.map(k => {
      const c = CIVS[k];
      return `<div class="civ-card ${k === this.myCiv ? 'sel' : ''}" data-civ="${k}">
        <div class="cn">${c.name}</div><div class="cb">${c.blurb}</div>
        <ul>${c.bonuses.map(b => `<li>${b}</li>`).join('')}</ul>
        <div class="lacks">Lacks: ${c.disabled.map(displayName).join(', ')}</div></div>`;
    }).join('');
    civSel.addEventListener('click', e => {
      const card = e.target.closest('.civ-card'); if (!card) return;
      this.myCiv = card.dataset.civ;
      civSel.querySelectorAll('.civ-card').forEach(c => c.classList.toggle('sel', c === card));
    });
    this.opps = [{ civ: 'random', difficulty: 'normal' }, { civ: 'random', difficulty: 'normal' }];
    this.renderOpps();
    document.getElementById('add-opp').onclick = () => { if (this.opps.length < 5) { this.opps.push({ civ: 'random', difficulty: 'normal' }); this.renderOpps(); } };
    document.getElementById('start-btn').onclick = () => this.startFromMenu();
    document.getElementById('howto-btn').onclick = () => this.showHelp(true);
    const mt = document.getElementById('m-map');
    mt.innerHTML = Object.entries(MAP_TYPES).map(([k, v]) => `<option value="${k}">${v.name}</option>`).join('');
  },
  renderOpps() {
    const el = document.getElementById('opp-list');
    el.innerHTML = this.opps.map((o, i) => `<div class="opp">
      <span class="dot" style="background:${PLAYER_COLORS[i + 2]}"></span>
      <select data-i="${i}" data-f="civ"><option value="random">Random civ</option>${CIV_KEYS.map(k => `<option value="${k}" ${o.civ === k ? 'selected' : ''}>${CIVS[k].name}</option>`).join('')}</select>
      <select data-i="${i}" data-f="difficulty">${['easy', 'normal', 'hard'].map(d => `<option ${o.difficulty === d ? 'selected' : ''}>${d}</option>`).join('')}</select>
      ${this.opps.length > 1 ? `<button data-rm="${i}" title="Remove">✕</button>` : ''}</div>`).join('');
    el.querySelectorAll('select').forEach(s => s.onchange = () => { this.opps[+s.dataset.i][s.dataset.f] = s.value; });
    el.querySelectorAll('button[data-rm]').forEach(b => b.onclick = () => { this.opps.splice(+b.dataset.rm, 1); this.renderOpps(); });
  },
  startFromMenu() {
    const val = id => document.getElementById(id).value;
    const spectate = document.getElementById('m-spectate').checked;
    const players = [];
    const used = new Set();
    if (!spectate) { players.push({ civ: this.myCiv, human: true, name: val('m-name') || 'You' }); used.add(this.myCiv); }
    const pickCiv = c => {
      if (c !== 'random') return c;
      const free = CIV_KEYS.filter(k => !used.has(k));
      const arr = free.length ? free : CIV_KEYS;
      return arr[Math.floor(Math.random() * arr.length)];
    };
    const oppCount = spectate ? Math.max(2, this.opps.length) : this.opps.length;
    for (let i = 0; i < oppCount; i++) {
      const o = this.opps[i] || { civ: 'random', difficulty: 'normal' };
      const civ = pickCiv(o.civ); used.add(civ);
      players.push({ civ, ai: true, difficulty: o.difficulty, name: CIVS[civ].leader });
    }
    this.speed = +val('m-speed');
    this.start({
      seed: Math.floor(Math.random() * 1e9), mapType: val('m-map'), mapSize: val('m-size'), startRes: val('m-res'),
      popLimit: +val('m-pop'), wonderTime: +val('m-wonder'), teams: val('m-teams'),
      reveal: document.getElementById('m-reveal').checked, observer: spectate, players,
    });
  },

  /* ---------- lifecycle ---------- */
  start(opts) {
    this.stop();
    this.lastOpts = opts;
    document.getElementById('menu').style.display = 'none';
    document.getElementById('game').style.display = 'block';
    this.closeOverlays();
    const loading = document.getElementById('loading');
    loading.style.display = 'flex';
    setTimeout(() => {
      const game = new Game(opts);
      this.game = game;
      for (let i = 0; i < (opts.fastForward || 0) / SIM_DT; i++) game.step();
      const pid = opts.observer ? 0 : 1;
      const cv = document.getElementById('view'), mm = document.getElementById('minimap');
      this.renderer = new Renderer(cv, mm, game, pid);
      this.ui = new UI(game, this.renderer, pid, this);
      this.input = new Input(this.ui, this.renderer, cv, mm, this);
      this.resize();
      const me = pid ? game.players[pid] : null;
      const tc = game.buildings.find(b => b.type === 'towncenter' && (!me || b.owner === pid));
      if (opts.zoom) this.renderer.cam.zoom = opts.zoom;
      if (tc) this.renderer.centerOn(tc.x, tc.y + 40);
      this.paused = false; this.running = true;
      this.acc = 0; this.last = performance.now();
      if (me) {
        game.msg(pid, `You lead the ${me.civName}. Gather food, wood, gold and stone, build houses, and advance through the ages. Build a Wonder or conquer every rival.`, 'good');
        game.msg(pid, 'Tip: Tool Age needs two of Barracks, Granary, Storage Pit or Dock. Your villagers need houses — population is capped.', 'info');
      }
      loading.style.display = 'none';
      requestAnimationFrame(this.loopFn);
    }, 30);
  },
  stop() {
    this.running = false;
    if (this.input) this.input.destroy();
    this.game = null; this.ui = null; this.renderer = null; this.input = null;
  },
  quitToMenu() {
    this.stop();
    this.closeOverlays();
    document.getElementById('game').style.display = 'none';
    document.getElementById('menu').style.display = 'flex';
  },
  restart() { if (this.lastOpts) this.start(Object.assign({}, this.lastOpts, { seed: Math.floor(Math.random() * 1e9) })); },
  resize() {
    if (!this.renderer) return;
    this.renderer.resize(window.innerWidth, window.innerHeight);
    this.renderer.clampCam();
  },
  frame(now) {
    if (!this.running) return;
    const dt = Math.min(0.25, (now - this.last) / 1000);
    this.last = now;
    const g = this.game;
    if (!this.paused) {
      this.acc += dt * this.speed;
      let n = 0;
      while (this.acc >= SIM_DT && n < 10) {
        for (const u of g.units) { u.px = u.x; u.py = u.y; }
        g.step();
        this.acc -= SIM_DT; n++;
      }
      if (n >= 10) this.acc = 0;
    }
    this.input.update(dt);
    this.renderer.draw(this.paused ? 1 : this.acc / SIM_DT, this.ui);
    this.renderer.drawMinimap(this.ui);
    this.ui.update(dt);
    requestAnimationFrame(this.loopFn);
  },
  cycleSpeed(dir) {
    const i = this.speeds.indexOf(this.speed);
    this.speed = this.speeds[clamp((i < 0 ? 2 : i) + dir, 0, this.speeds.length - 1)];
  },

  /* ---------- overlays ---------- */
  overlayOpen() { return document.getElementById('overlay').style.display === 'flex'; },
  closeOverlays() {
    const o = document.getElementById('overlay');
    o.style.display = 'none';
    if (this.endShown) return;
    this.paused = false;
  },
  openOverlay(html, pause) {
    const o = document.getElementById('overlay');
    document.getElementById('overlay-box').innerHTML = html;
    o.style.display = 'flex';
    if (pause) this.paused = true;
    o.querySelectorAll('[data-act]').forEach(b => b.onclick = () => this.overlayAction(b.dataset.act));
  },
  overlayAction(a) {
    if (a === 'resume') this.closeOverlays();
    else if (a === 'help') this.showHelp();
    else if (a === 'civs') this.showCivs();
    else if (a === 'sound') { Sound.enabled = !Sound.enabled; this.togglePause(true); }
    else if (a === 'restart') { this.endShown = false; this.restart(); }
    else if (a === 'menu') { this.endShown = false; this.quitToMenu(); }
    else if (a === 'watch') { this.endShown = false; this.closeOverlays(); }
    else if (a === 'back') { if (this.game) this.togglePause(true); else this.closeOverlays(); }
  },
  togglePause(open) {
    if (!this.game) return;
    if (!open && this.overlayOpen()) { this.closeOverlays(); return; }
    this.openOverlay(`<h2>Paused</h2><div class="btns col">
      <button data-act="resume">Resume</button>
      <button data-act="help">How to play</button>
      <button data-act="civs">Civilisations &amp; tech tree</button>
      <button data-act="sound">Sound: ${Sound.enabled ? 'On' : 'Off'}</button>
      <button data-act="restart">Restart (new map)</button>
      <button data-act="menu">Quit to main menu</button></div>`, true);
  },
  showHelp(fromMenu) {
    this.openOverlay(`<h2>How to play</h2><div class="help">
      <h3>Economy — four resources</h3>
      <ul>
        <li><b>Food</b> comes from separate sources: <i>forage</i> berry bushes; <i>hunt</i> gazelles and elephants (kill them, then butcher the carcass before it rots away); <i>fish</i> with Fishing Boats from a Dock; and <i>farm</i> (Tool Age, needs a Market) — each farm holds a limited amount of food, then is exhausted and must be rebuilt.</li>
        <li><b>Wood</b>: chop trees — felled trees disappear from the map. <b>Gold</b> and <b>stone</b>: mine veins until they run out.</li>
        <li>Villagers carry 10 at a time and must walk back to a drop-off: <b>Granary</b> (berries, meat, crops), <b>Storage Pit</b> (wood, gold, stone), <b>Dock</b> (fish, boats only) or the <b>Town Centre</b> (everything but fish).</li>
        <li><b>Houses</b> each support 4 population (Town Centre 4). You cannot train beyond your housing or the population limit.</li>
      </ul>
      <h3>Ages</h3>
      <ul>
        <li>Research the next age at the Town Centre. Each needs <b>two different completed buildings</b> of the current age:
          Tool Age ← 2 of Barracks / Granary / Storage Pit / Dock (500 food);
          Bronze Age ← 2 of Market / Archery Range / Stable (800 food, 500 gold);
          Iron Age ← 2 of Temple / Siege Workshop / Academy / Government Centre (1000 food, 800 gold).</li>
        <li>Each age unlocks new buildings, units and technologies — hover any button to see what it needs.</li>
      </ul>
      <h3>War</h3>
      <ul>
        <li>Walls and towers (researched at the Granary) can be built anywhere. Drag to lay a wall line.</li>
        <li><b>Priests</b> never fight: right-click an enemy and the priest chants for several seconds. If it is not interrupted, the target converts to your side. Faith then recharges. Chariots resist; Monotheism lets priests convert buildings and other priests.</li>
        <li>Siege engines smash buildings from range but cannot fire up close. Warships and Catapult Triremes rule the water.</li>
      </ul>
      <h3>Victory</h3>
      <ul><li>Destroy every enemy unit and building (walls excepted), or build a <b>Wonder</b> in the Iron Age and keep it standing through the countdown. Every player is warned when a Wonder is started, at each 25% and every minute of its countdown.</li></ul>
      <h3>Controls</h3>
      <ul>
        <li>Left-click select · drag box-select · double-click selects all of a type · Shift adds.</li>
        <li>Right-click: move, gather, build/repair, attack, convert, set rally point.</li>
        <li>Arrow keys / screen edge scroll · mouse wheel zoom · minimap click to jump, right-click to move.</li>
        <li>Command grid hotkeys Q W E R T / A S D F G / Z X C V B · Shift-click a unit button to queue 5.</li>
        <li>H Town Centre · . idle villager · Ctrl+1–9 set group, 1–9 recall · Space last alert · Delete · Esc cancel · +/- speed · Tab scores · P / F10 pause.</li>
      </ul></div>
      <div class="btns"><button data-act="${fromMenu ? 'resume' : 'back'}">Back</button></div>`, !fromMenu);
  },
  showCivs() {
    const rows = CIV_KEYS.map(k => {
      const c = CIVS[k];
      return `<tr><td><b>${c.name}</b><br><small>${c.blurb}</small></td><td>${c.bonuses.join('<br>')}</td><td class="bad">${c.disabled.map(displayName).join(', ')}</td></tr>`;
    }).join('');
    this.openOverlay(`<h2>Civilisations</h2><p>Each civilisation has its own economic and military bonuses and a different technology tree. Missing items appear crossed out on its command buttons.</p>
      <div class="civ-table"><table><tr><th>Civilisation</th><th>Bonuses</th><th>Cannot build / research</th></tr>${rows}</table></div>
      <div class="btns"><button data-act="${this.game ? 'back' : 'resume'}">Back</button></div>`, true);
  },
  showEnd(won, e) {
    if (!this.game) return;
    this.endShown = true;
    const g = this.game;
    const title = won === null ? 'Game over' : won ? 'Victory!' : 'Defeat';
    const reason = e.reason === 'wonder' ? 'through the glory of a Wonder' : 'by conquest';
    const winners = g.players.filter(p => p.id && p.team === e.team).map(p => p.name + ' (' + p.civName + ')').join(' & ');
    const rows = g.players.filter(p => p.id).map(p => {
      const s = p.stats;
      return `<tr><td><span class="dot" style="background:${p.color}"></span>${p.name}</td><td>${p.civName}</td><td>${AGE_NAMES[p.age]}</td>
        <td>${RES_KEYS.map(k => Math.floor(s.gathered[k])).join(' / ')}</td><td>${s.trained}</td><td>${s.killed}</td><td>${s.lost}</td><td>${s.razed}</td><td>${s.converted}</td><td>${s.techs}</td>
        <td>${s.ageTimes.slice(1).map(t => t == null ? '–' : fmtTime(t)).join(' / ')}</td></tr>`;
    }).join('');
    this.openOverlay(`<h2 class="${won === false ? 'bad' : 'good'}">${title}</h2><p>${winners || 'Nobody'} won ${reason} after ${fmtTime(g.time)}.</p>
      <div class="civ-table"><table><tr><th>Player</th><th>Civ</th><th>Age</th><th>Gathered F/W/G/S</th><th>Trained</th><th>Kills</th><th>Lost</th><th>Razed</th><th>Converted</th><th>Techs</th><th>Tool/Bronze/Iron at</th></tr>${rows}</table></div>
      <div class="btns"><button data-act="watch">Keep watching</button><button data-act="restart">Play again</button><button data-act="menu">Main menu</button></div>`, false);
  },
};

window.addEventListener('DOMContentLoaded', () => App.init());
"},{"path":"js/map.js","type":"text/javascript","text":"'use strict';
/* Procedural map generation: terrain, start positions, resources and wildlife. */

const T_GRASS = 0, T_SAND = 1, T_WATER = 2;
const MAP_SIZES = { small: 88, medium: 112, large: 136 };
const MAP_TYPES = {
  inland: { name: 'Inland Sea', desc: 'A great sea in the middle, coastlines for every empire.' },
  coastal: { name: 'Coastal', desc: 'An open ocean along one flank of the continent.' },
  lakes: { name: 'Lakes', desc: 'Rolling land dotted with lakes.' },
  highlands: { name: 'Highlands', desc: 'Mostly land with only small ponds. Few naval options.' },
};

function generateMap(game) {
  const W = game.W, H = game.H, rng = game.rng;
  const T = game.terrain;
  const noise = new ValueNoise(rng);
  const type = game.opts.mapType || 'inland';
  const nPlayers = game.players.length - 1;
  const reserve = new Uint8Array(W * H); // tiles kept clear around town centres

  // ----- water field -----
  const cx = W / 2, cy = H / 2;
  const coastAngle = rng() * Math.PI * 2;
  for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) {
    const n = noise.fbm(x / 13, y / 13, 3);
    let water = false;
    if (type === 'inland') {
