    ringCy = cy - Math.sin(coastAngle) * H * 0.1;
    ringR = W * 0.32;
  }
  const a0 = rng() * Math.PI * 2;
  for (let i = 0; i < nPlayers; i++) {
    const a = a0 + (i / nPlayers) * Math.PI * 2 + (rng() - 0.5) * 0.25;
    let sx = Math.round(ringCx + Math.cos(a) * ringR), sy = Math.round(ringCy + Math.sin(a) * ringR);
