    if (sp) placeCluster('bush', sp.x, sp.y, 5);
    sp = findSpot(W / 2, H / 2, 0, W * 0.48, 1, 16);
    if (sp) herd('gazelle', sp.x, sp.y, 3 + Math.floor(rng() * 3));
