    for (const [x, y] of waterTiles) {
      if (add <= 0) break;
      if (Math.hypot(x - s.x, y - s.y) > 24) continue;
      let ok = true;
      for (let dy = -1; dy <= 1 && ok; dy++) for (let dx = -1; dx <= 1; dx++) if (!isFreeWater(x + dx, y + dy)) { ok = false; break; }
      if (ok) { game.spawnResource('fish', x, y); add--; }
