/* Grid A* pathfinding with 8-way movement, no corner cutting, rectangular goals and partial paths. */

class PathFinder {
  constructor(game) {
    this.game = game;
    const N = game.W * game.H;
    this.g = new Float32Array(N);
    this.par = new Int32Array(N);
    this.seen = new Uint32Array(N);
    this.closed = new Uint32Array(N);
    this.gen = 0;
    this.heap = new MinHeap();
  }

  /* goal: {x0,y0,x1,y1, inside} in tiles (inclusive). inside=true -> must stand in rect, else adjacent to it.
     Returns {tiles:[[x,y]...], reached, nodes} */
  find(sx, sy, goal, naval, maxNodes) {
    const game = this.game, W = game.W, H = game.H;
    const occ = game.occ, terr = game.terrain;
    const gx0 = goal.x0, gy0 = goal.y0, gx1 = goal.x1, gy1 = goal.y1, inside = goal.inside;
    sx = clamp(sx, 0, W - 1); sy = clamp(sy, 0, H - 1);
    const goalAt = (x, y) => {
      const dx = x < gx0 ? gx0 - x : x > gx1 ? x - gx1 : 0;
      const dy = y < gy0 ? gy0 - y : y > gy1 ? y - gy1 : 0;
      return inside ? (dx === 0 && dy === 0) : (dx <= 1 && dy <= 1 && (dx + dy) > 0);
    };
    if (goalAt(sx, sy)) return { tiles: [], reached: true, nodes: 0, exhausted: false };

    this.gen++;
    if (this.gen > 4000000000) { this.gen = 1; this.seen.fill(0); this.closed.fill(0); }
    const gen = this.gen, g = this.g, par = this.par, seen = this.seen, closed = this.closed;
    const heap = this.heap; heap.clear();
    const si = sy * W + sx;
    const h0 = (() => { const dx = sx < gx0 ? gx0 - sx : sx > gx1 ? sx - gx1 : 0, dy = sy < gy0 ? gy0 - sy : sy > gy1 ? sy - gy1 : 0; return dx > dy ? dx + 0.4142 * dy : dy + 0.4142 * dx; })();
    g[si] = 0; seen[si] = gen; par[si] = -1;
    heap.push(si, h0);
    let best = si, bestH = h0, bestG = 0, nodes = 0;
    let found = -1, exhausted = true;
    const want = naval ? T_WATER : -1;
    while (heap.size) {
      const i = heap.pop();
      if (closed[i] === gen) continue;
      closed[i] = gen; nodes++;
      const x = i % W, y = (i / W) | 0;
      const hdx = x < gx0 ? gx0 - x : x > gx1 ? x - gx1 : 0;
      const hdy = y < gy0 ? gy0 - y : y > gy1 ? y - gy1 : 0;
      if (inside ? (hdx === 0 && hdy === 0) : (hdx <= 1 && hdy <= 1 && (hdx + hdy) > 0)) { found = i; break; }
      const hh = hdx > hdy ? hdx + 0.4142 * hdy : hdy + 0.4142 * hdx;
      if (hh < bestH || (hh === bestH && g[i] < bestG)) { bestH = hh; best = i; bestG = g[i]; }
      if (nodes > maxNodes) { exhausted = false; break; }
      const gi = g[i];
      // passability of the 8 neighbours
      for (let d = 0; d < 8; d++) {
        let nx, ny;
        switch (d) {
          case 0: nx = x + 1; ny = y; break; case 1: nx = x - 1; ny = y; break;
          case 2: nx = x; ny = y + 1; break; case 3: nx = x; ny = y - 1; break;
          case 4: nx = x + 1; ny = y + 1; break; case 5: nx = x + 1; ny = y - 1; break;
          case 6: nx = x - 1; ny = y + 1; break; default: nx = x - 1; ny = y - 1;
        }
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
        const ni = ny * W + nx;
        if (occ[ni] || (naval ? terr[ni] !== want : terr[ni] === T_WATER)) continue;
        if (d >= 4) {
          const a = y * W + nx, b = ny * W + x;
          if (occ[a] || (naval ? terr[a] !== want : terr[a] === T_WATER)) continue;
          if (occ[b] || (naval ? terr[b] !== want : terr[b] === T_WATER)) continue;
        }
        if (closed[ni] === gen) continue;
        const ng = gi + (d >= 4 ? 1.4142 : 1);
        if (seen[ni] !== gen || ng < g[ni]) {
          seen[ni] = gen; g[ni] = ng; par[ni] = i;
          const ddx = nx < gx0 ? gx0 - nx : nx > gx1 ? nx - gx1 : 0;
          const ddy = ny < gy0 ? gy0 - ny : ny > gy1 ? ny - gy1 : 0;
          heap.push(ni, ng + (ddx > ddy ? ddx + 0.4142 * ddy : ddy + 0.4142 * ddx) * 1.02);
        }
      }
    }
    if (found >= 0) exhausted = false;
    const end = found >= 0 ? found : best;
    const tiles = [];
    let c = end;
    while (c !== -1 && c !== si) { tiles.push([c % W, (c / W) | 0]); c = par[c]; }
    tiles.reverse();
    return { tiles, reached: found >= 0, nodes, exhausted };
  }

  /* Check that a straight segment (px) is walkable, using samples on the centre line and both flanks */
  lineClear(ax, ay, bx, by, naval, rad) {
    const game = this.game;
    const dx = bx - ax, dy = by - ay;
    const L = Math.hypot(dx, dy);
    if (L < 1) return true;
    const nx = -dy / L * rad, ny = dx / L * rad;
    const steps = Math.ceil(L / 8);
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const px = ax + dx * t, py = ay + dy * t;
      if (!game.passablePx(px, py, naval)) return false;
      if (rad > 0 && (!game.passablePx(px + nx, py + ny, naval) || !game.passablePx(px - nx, py - ny, naval))) return false;
    }
    return true;
  }

  /* Convert tile path into smoothed pixel waypoints */
  smooth(startX, startY, tiles, naval, rad, endPoint) {
    const pts = tiles.map(t => ({ x: (t[0] + 0.5) * TILE, y: (t[1] + 0.5) * TILE }));
    if (endPoint && pts.length) pts[pts.length - 1] = { x: endPoint.x, y: endPoint.y };
    if (pts.length <= 1) return pts;
    const out = [];
    let cx = startX, cy = startY, i = 0;
    while (i < pts.length) {
      let j = Math.min(pts.length - 1, i + 12);
      while (j > i && !this.lineClear(cx, cy, pts[j].x, pts[j].y, naval, rad)) j--;
      out.push(pts[j]);
      cx = pts[j].x; cy = pts[j].y;
      i = j + 1;
    }
    return out;
  }
}
