/* Canvas renderer: terrain chunks, entities, effects, fog of war, placement ghosts and the minimap. */

const CHUNK = 16;

class Renderer {
  constructor(canvas, minimap, game, viewerId) {
    this.cv = canvas; this.ctx = canvas.getContext('2d');
    this.mm = minimap; this.mctx = minimap.getContext('2d');
    this.g = game; this.viewer = viewerId; // player id or 0 for observer
    this.cam = { x: 0, y: 0, zoom: 1 };
    this.chunks = new Map();
    this.noise = new ValueNoise(mulberry32((game.opts.seed || 1) * 7 + 3));
    this.computeDepth();
    const W = game.W, H = game.H;
    this.fogCv = document.createElement('canvas'); this.fogCv.width = W; this.fogCv.height = H;
    this.fogCtx = this.fogCv.getContext('2d');
    this.fogImg = this.fogCtx.createImageData(W, H);
    this.fogTick = -1;
    this.mmBase = document.createElement('canvas'); this.mmBase.width = W; this.mmBase.height = H;
    this.mmCtx = this.mmBase.getContext('2d');
    this.mmImg = this.mmCtx.createImageData(W, H);
    this.mmT = 0;
    this.terrainRGB = new Uint8Array(W * H * 3);
    for (let i = 0; i < W * H; i++) {
      const t = game.terrain[i];
      const c = t === T_WATER ? (this.depth[i] > 2 ? [36, 96, 142] : [64, 138, 186]) : t === T_SAND ? [214, 196, 138] : [104, 148, 62];
      this.terrainRGB[i * 3] = c[0]; this.terrainRGB[i * 3 + 1] = c[1]; this.terrainRGB[i * 3 + 2] = c[2];
    }
    this.pings = [];
  }
  get player() { return this.viewer ? this.g.players[this.viewer] : null; }

  computeDepth() {
    const g = this.g, W = g.W, H = g.H;
    const d = new Uint8Array(W * H).fill(255);
    const q = [];
    for (let i = 0; i < W * H; i++) if (g.terrain[i] !== T_WATER) { d[i] = 0; q.push(i); }
    for (let qi = 0; qi < q.length; qi++) {
      const i = q[qi], x = i % W, y = (i / W) | 0;
      if (d[i] >= 6) continue;
      for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const nx = x + dx, ny = y + dy;
        if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
        const ni = ny * W + nx;
        if (d[ni] > d[i] + 1) { d[ni] = d[i] + 1; q.push(ni); }
      }
    }
