    if (isSel) { c.strokeStyle = b.owner === this.viewer ? '#ffffff' : '#ff5a4a'; c.lineWidth = 1.5; c.strokeRect(b.tx * TILE + 1, b.ty * TILE + 1, S - 2, S - 2); }
    const style = p.civDef ? p.civDef.style : 'desert';
    Sprites.drawBuilding(c, b, p.color, p.age, style, t);
    if (g.time - b.hitT < 0.12) { c.fillStyle = 'rgba(255,60,40,0.18)'; c.fillRect(b.tx * TILE, b.ty * TILE - S * 0.4, S, S * 1.4); }
    // damage smoke
    if (b.built && b.hp < b.maxHp * 0.5 && !b.walkable) {
      const n = b.hp < b.maxHp * 0.25 ? 3 : 1;
      for (let i = 0; i < n; i++) {
        const ph = (t * 0.5 + i * 0.33 + b.id * 0.1) % 1;
        c.fillStyle = `rgba(60,55,50,${0.45 * (1 - ph)})`;
        c.beginPath(); c.arc(b.x - S * 0.2 + i * S * 0.2, b.y - S * 0.3 - ph * 30, 5 + ph * 10, 0, Math.PI * 2); c.fill();
      }
      c.fillStyle = `rgba(255,${120 + Math.sin(t * 9) * 40},30,0.8)`;
      c.beginPath(); c.arc(b.x - S * 0.15, b.y - S * 0.1, 3 + Math.sin(t * 11) * 1, 0, Math.PI * 2); c.fill();
    }
    const hurt = b.hp < b.maxHp && g.time - b.hitT < 5;
    if (isSel || hurt || !b.built) {
      const frac = b.built ? b.hp / b.maxHp : b.progress;
      this.hpBar(c, b.x, b.ty * TILE - (b.type === 'tower' ? 50 : b.type === 'wonder' ? 130 : 22), Math.min(80, S * 0.8), frac, b.built ? null : '#e0b040');
    }
    if (b.built && b.queue.length && b.owner === this.viewer && isSel) {
      const q = b.queue[0];
      this.hpBar(c, b.x, (b.ty + b.size) * TILE + 4, Math.min(70, S * 0.7), q.progress, '#6aa8ff');
    }
  }
  drawRubble(c, f) {
    const a = Math.min(1, (f.dur - f.t) / 4);
    c.globalAlpha = a;
    const S = f.size * TILE;
    c.fillStyle = 'rgba(80,65,50,0.6)'; c.fillRect(f.x - S / 2 + 3, f.y - S / 2 + 3, S - 6, S - 6);
    c.fillStyle = '#8a7a66';
    for (let i = 0; i < f.size * 6; i++) {
      const hx = hash2(f.x + i, f.y - i), hy = hash2(f.y + i * 3, f.x);
      c.fillRect(f.x - S / 2 + 4 + hx * (S - 12), f.y - S / 2 + 4 + hy * (S - 12), 4 + hx * 4, 3 + hy * 3);
    }
    c.globalAlpha = 1;
  }
  drawGhost(c, ui, t) {
    const g = this.g, pl = ui.placing, p = this.player;
    if (!pl || !p) return;
    const d = BUILDINGS[pl.type];
    const tiles = pl.wallLine ? g.wallTiles(pl.wallLine.x0, pl.wallLine.y0, pl.tx, pl.ty) : [[pl.tx, pl.ty]];
    let cost = 0;
    for (const [tx, ty] of tiles) {
      const ok = g.canPlace(p.id, pl.type, tx, ty, true).ok && (pl.wallLine ? p.res.stone >= (cost += p.bs('wall').cost.stone) : true);
      const S = d.size * TILE;
      const fake = { type: pl.type, tx, ty, size: d.size, x: (tx + d.size / 2) * TILE, y: (ty + d.size / 2) * TILE, built: true, progress: 1, food: 250, maxFood: 250, conn: 0, walkable: d.walkable, hp: 1, maxHp: 1 };
      c.save(); c.globalAlpha = 0.55;
      Sprites.drawBuilding(c, fake, p.color, p.age, p.civDef.style, t);
      c.restore();
      c.fillStyle = ok ? 'rgba(80,255,80,0.22)' : 'rgba(255,60,60,0.32)';
      c.fillRect(tx * TILE, ty * TILE, S, S);
      c.strokeStyle = ok ? 'rgba(120,255,120,0.8)' : 'rgba(255,90,90,0.9)'; c.lineWidth = 1;
      c.strokeRect(tx * TILE + 0.5, ty * TILE + 0.5, S - 1, S - 1);
    }
    if (d.atk) {
      const bs = p.bs(pl.type);
      c.strokeStyle = 'rgba(255,255,255,0.3)'; c.setLineDash([6, 6]);
      c.beginPath(); c.arc((pl.tx + 0.5) * TILE, (pl.ty + 0.5) * TILE, bs.range * TILE, 0, Math.PI * 2); c.stroke(); c.setLineDash([]);
