  }

  /* ---------- minimap ---------- */
  drawMinimap(ui) {
    const g = this.g, W = g.W, H = g.H;
    const now = performance.now();
    const mc = this.mctx, mw = this.mm.width, mh = this.mm.height;
    if (now - this.mmT > 400) {
      this.mmT = now;
      const d = this.mmImg.data, rgb = this.terrainRGB;
      const p = this.player;
      for (let i = 0; i < W * H; i++) { d[i * 4] = rgb[i * 3]; d[i * 4 + 1] = rgb[i * 3 + 1]; d[i * 4 + 2] = rgb[i * 3 + 2]; d[i * 4 + 3] = 255; }
      const put = (x, y, r, gg, b) => { if (x < 0 || y < 0 || x >= W || y >= H) return; const o = (y * W + x) * 4; d[o] = r; d[o + 1] = gg; d[o + 2] = b; };
      for (const r of g.resources) {
        if (r.dead || r.type === 'carcass') continue;
        const c = r.type === 'tree' ? [30, 80, 30] : r.type === 'gold' ? [240, 200, 60] : r.type === 'stone' ? [170, 170, 180] : r.type === 'bush' ? [200, 60, 90] : [150, 200, 230];
        put(r.tx, r.ty, c[0], c[1], c[2]);
      }
      const rgbOf = hex => { const n = parseInt(hex.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; };
      for (const b of g.buildings) {
        if (b.dead || !this.entVisible(b)) continue;
        const c = rgbOf(g.players[b.owner].color);
        for (let y = b.ty; y < b.ty + b.size; y++) for (let x = b.tx; x < b.tx + b.size; x++) put(x, y, c[0], c[1], c[2]);
      }
      for (const u of g.units) {
        if (u.dead || !this.entVisible(u)) continue;
        const c = u.owner === 0 ? [235, 225, 200] : rgbOf(g.players[u.owner].color);
        const x = Math.floor(u.x / TILE), y = Math.floor(u.y / TILE);
        put(x, y, c[0], c[1], c[2]);
        if (u.owner) put(x + 1, y, c[0], c[1], c[2]);
      }
      if (p && p.explored) {
        for (let i = 0; i < W * H; i++) {
          if (!p.explored[i]) { d[i * 4] = 8; d[i * 4 + 1] = 8; d[i * 4 + 2] = 8; }
          else if (!p.visible[i]) { d[i * 4] *= 0.6; d[i * 4 + 1] *= 0.6; d[i * 4 + 2] *= 0.6; }
        }
      }
      this.mmCtx.putImageData(this.mmImg, 0, 0);
    }
    mc.imageSmoothingEnabled = false;
    mc.fillStyle = '#000'; mc.fillRect(0, 0, mw, mh);
    mc.drawImage(this.mmBase, 0, 0, mw, mh);
    const sx = mw / (W * TILE), sy = mh / (H * TILE);
    // wonders always marked
    const tt = now / 1000;
    for (const b of g.buildings) {
      if (b.dead || !BUILDINGS[b.type].wonder) continue;
      mc.strokeStyle = g.players[b.owner].color; mc.lineWidth = 2;
      mc.beginPath(); mc.arc(b.x * sx, b.y * sy, 6 + Math.sin(tt * 5) * 2, 0, Math.PI * 2); mc.stroke();
    }
    // alert pings
    this.pings = this.pings.filter(p => tt - p.t < 3);
    for (const p of this.pings) {
      const k = (tt - p.t) / 3;
      mc.strokeStyle = p.color || '#ff4030'; mc.lineWidth = 2; mc.globalAlpha = 1 - k;
      mc.beginPath(); mc.arc(p.x * sx, p.y * sy, 4 + k * 14, 0, Math.PI * 2); mc.stroke();
      mc.globalAlpha = 1;
    }
    const cam = this.cam;
    mc.strokeStyle = '#fff'; mc.lineWidth = 1;
    mc.strokeRect(cam.x * sx, cam.y * sy, this.vw / cam.zoom * sx, (this.vh - 170) / cam.zoom * sy);
  }
  ping(x, y, color) { this.pings.push({ x, y, t: performance.now() / 1000, color }); }
}
"},{"path":"js/sound.js","type":"text/javascript","text":"'use strict';
/* Tiny WebAudio synthesiser – all sounds are generated, nothing is loaded. */

const Sound = (() => {
  let ac = null, master = null, enabled = true, volume = 0.5;
  const last = {};
  function ctx() {
    if (!ac) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ac = new AC();
      master = ac.createGain(); master.gain.value = volume; master.connect(ac.destination);
    }
    if (ac.state === 'suspended') ac.resume();
    return ac;
  }
  function tone(freq, start, dur, type, gain, opts) {
    const a = ac, o = a.createOscillator(), g = a.createGain();
    o.type = type || 'sine';
    o.frequency.setValueAtTime(freq, start);
    if (opts && opts.slide) o.frequency.exponentialRampToValueAtTime(opts.slide, start + dur);
    if (opts && opts.vib) {
      const l = a.createOscillator(), lg = a.createGain();
      l.frequency.value = opts.vib; lg.gain.value = freq * 0.03;
      l.connect(lg); lg.connect(o.frequency); l.start(start); l.stop(start + dur);
    }
    g.gain.setValueAtTime(0.0001, start);
    g.gain.exponentialRampToValueAtTime(gain, start + Math.min(0.03, dur * 0.2));
    g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
    let node = o;
    if (opts && opts.lp) { const f = a.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = opts.lp; o.connect(f); node = f; }
    node.connect(g); g.connect(master);
    o.start(start); o.stop(start + dur + 0.05);
  }
  function noise(start, dur, gain, lp) {
    const a = ac;
    const len = Math.floor(a.sampleRate * dur);
    const buf = a.createBuffer(1, len, a.sampleRate);
    const d = buf.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const s = a.createBufferSource(); s.buffer = buf;
    const f = a.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = lp || 800;
    const g = a.createGain(); g.gain.value = gain;
    s.connect(f); f.connect(g); g.connect(master);
    s.start(start);
  }
  function chant(t) {
    // "wo-lo-lo": voiced sawtooth through a sweeping formant filter
    const a = ac;
    const sy = [[220, 500, 0.32], [247, 900, 0.22], [220, 700, 0.42]];
    let tt = t;
    for (const [f, form, d] of sy) {
      const o = a.createOscillator(); o.type = 'sawtooth'; o.frequency.setValueAtTime(f, tt);
      const bp = a.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 6; bp.frequency.setValueAtTime(form * 0.7, tt); bp.frequency.linearRampToValueAtTime(form, tt + d);
      const g = a.createGain(); g.gain.setValueAtTime(0.0001, tt); g.gain.exponentialRampToValueAtTime(0.35, tt + 0.04); g.gain.exponentialRampToValueAtTime(0.0001, tt + d);
      o.connect(bp); bp.connect(g); g.connect(master);
      o.start(tt); o.stop(tt + d + 0.05);
      tt += d * 0.85;
    }
  }
  const SOUNDS = {
    click: t => tone(900, t, 0.05, 'square', 0.05),
    error: t => { tone(160, t, 0.12, 'square', 0.08); tone(120, t + 0.12, 0.15, 'square', 0.08); },
    trained: t => { tone(660, t, 0.12, 'triangle', 0.08); tone(880, t + 0.08, 0.15, 'triangle', 0.06); },
    built: t => { noise(t, 0.06, 0.25, 1500); noise(t + 0.14, 0.06, 0.25, 1500); tone(330, t + 0.28, 0.25, 'triangle', 0.08); },
    research: t => { tone(523, t, 0.2, 'sine', 0.08); tone(659, t + 0.12, 0.2, 'sine', 0.08); tone(784, t + 0.24, 0.35, 'sine', 0.08); },
    ageup: t => { [392, 523, 659, 784, 1046].forEach((f, i) => tone(f, t + i * 0.13, 0.5, 'sawtooth', 0.06, { lp: 2200 })); },
    enemyage: t => { [294, 370, 440].forEach((f, i) => tone(f, t + i * 0.15, 0.4, 'sawtooth', 0.04, { lp: 1500 })); },
    alert: t => { tone(440, t, 0.18, 'sawtooth', 0.07, { lp: 1800 }); tone(330, t + 0.2, 0.25, 'sawtooth', 0.07, { lp: 1800 }); },
    horn: t => { tone(147, t, 1.1, 'sawtooth', 0.12, { lp: 700, vib: 5 }); tone(220, t + 0.2, 0.9, 'sawtooth', 0.07, { lp: 900, vib: 5 }); },
    wonder: t => { [110, 220, 331, 442, 663].forEach((f, i) => tone(f, t, 2.6 - i * 0.3, 'sine', 0.12 / (i + 1))); noise(t, 0.3, 0.15, 400); },
    chant: t => chant(t),
    converted: t => { tone(988, t, 0.5, 'sine', 0.08); tone(1319, t + 0.05, 0.6, 'sine', 0.05); },
    death: t => noise(t, 0.12, 0.08, 900),
    collapse: t => { noise(t, 0.8, 0.35, 300); tone(70, t, 0.6, 'sine', 0.15, { slide: 40 }); },
    defeat: t => { [392, 330, 262, 196].forEach((f, i) => tone(f, t + i * 0.3, 0.6, 'triangle', 0.1)); },
    victory: t => { [523, 659, 784, 1046, 784, 1046].forEach((f, i) => tone(f, t + i * 0.16, 0.5, 'sawtooth', 0.06, { lp: 2400 })); },
  };
  return {
    play(name) {
      if (!enabled) return;
      const a = ctx(); if (!a) return;
      const now = a.currentTime;
      const minGap = name === 'chant' ? 1.2 : name === 'death' ? 0.15 : name === 'wonder' || name === 'horn' ? 2 : 0.25;
      if (last[name] && now - last[name] < minGap) return;
      last[name] = now;
      const fn = SOUNDS[name];
      if (fn) try { fn(now + 0.01); } catch (e) { /* ignore audio errors */ }
    },
    unlock() { ctx(); },
    get enabled() { return enabled; },
    set enabled(v) { enabled = v; },
    setVolume(v) { volume = v; if (master) master.gain.value = v; },
  };
})();
"},{"path":"js/sprites.js","type":"text/javascript","text":"'use strict';
/* Procedural sprite painter: every unit, building, resource and icon is drawn with canvas paths. */

const Sprites = (() => {
  const SKIN = '#d9a46c';
  const MATS = {
    desert: [
      { wall: '#8d6b45', wallD: '#6a5034', roof: '#c9a85e', roofD: '#a08441', trim: '#5d4329' },
      { wall: '#c39a62', wallD: '#9a7748', roof: '#d8bf86', roofD: '#b49b62', trim: '#7d5d38' },
      { wall: '#d9c497', wallD: '#b39f73', roof: '#e8d9b0', roofD: '#c2b186', trim: '#8e7650' },
      { wall: '#ece4d0', wallD: '#c8bea6', roof: '#f3eddc', roofD: '#d3c9b0', trim: '#a69676' },
    ],
    greek: [
      { wall: '#8a6a46', wallD: '#684f34', roof: '#c4a35a', roofD: '#9b7f42', trim: '#5b4129' },
      { wall: '#bf9a6a', wallD: '#957650', roof: '#b0623e', roofD: '#8a4a2d', trim: '#6e5134' },
      { wall: '#ddd0b2', wallD: '#b7aa8c', roof: '#b4573a', roofD: '#8e412a', trim: '#8a7a5c' },
      { wall: '#f1ede2', wallD: '#cfc8b6', roof: '#a94f36', roofD: '#843a26', trim: '#9b917c' },
    ],
    asian: [
      { wall: '#87684a', wallD: '#654e37', roof: '#b99a58', roofD: '#927a42', trim: '#4f3a28' },
      { wall: '#b58f66', wallD: '#8c6e4d', roof: '#5f6a5a', roofD: '#465046', trim: '#6b3d2a' },
      { wall: '#cdb895', wallD: '#a89474', roof: '#3f5a55', roofD: '#2d4440', trim: '#8a3a2a' },
      { wall: '#e6dccb', wallD: '#c2b7a3', roof: '#2f4e5a', roofD: '#203a44', trim: '#9b2f25' },
    ],
  };

  function circle(c, x, y, r) { c.beginPath(); c.arc(x, y, r, 0, Math.PI * 2); c.fill(); }
  function ellipse(c, x, y, rx, ry) { c.beginPath(); c.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); c.fill(); }
  function line(c, x0, y0, x1, y1) { c.beginPath(); c.moveTo(x0, y0); c.lineTo(x1, y1); c.stroke(); }
  function poly(c, pts, fill, stroke) {
    c.beginPath(); c.moveTo(pts[0], pts[1]);
    for (let i = 2; i < pts.length; i += 2) c.lineTo(pts[i], pts[i + 1]);
    c.closePath();
    if (fill) { c.fillStyle = fill; c.fill(); }
    if (stroke) { c.strokeStyle = stroke; c.stroke(); }
  }
  function shadow(c, x, y, rx, ry) { c.fillStyle = 'rgba(0,0,0,0.28)'; ellipse(c, x, y, rx, ry); }

  /* ---------- people ---------- */
  function human(c, o) {
    // origin at feet; facing +x
    const leg = o.moving ? Math.sin(o.walk) * 3 : 0;
    c.lineCap = 'round';
    if (!o.mounted) {
      c.strokeStyle = o.legs || '#4e3420'; c.lineWidth = 2.2;
      line(c, -1.5, -6, -1.5 + leg, 0); line(c, 1.5, -6, 1.5 - leg, 0);
    }
    // back arm
    c.strokeStyle = SKIN; c.lineWidth = 1.8;
    line(c, -1, -11, -4 - leg * 0.3, -7);
    // body
    if (o.robe) {
      poly(c, [-4.5, -1, 4.5, -1, 3.2, -13, -3.2, -13], o.robe);
    } else {
      c.fillStyle = o.tunic; ellipse(c, 0, -9.5, 4, 5);
    }
    if (o.trim) { c.fillStyle = o.trim; c.fillRect(-4, -8.5, 8, 2); }
    if (o.armor) { c.fillStyle = o.armor; ellipse(c, 0, -11, 3.6, 3); }
    // head
    c.fillStyle = SKIN; circle(c, 0.5, -16.2, 3.1);
    if (o.helmet) {
      c.fillStyle = o.helmet; c.beginPath(); c.arc(0.5, -16.6, 3.3, Math.PI, 0); c.fill();
      if (o.crest) { c.fillStyle = o.crest; c.fillRect(-2.5, -21.5, 5, 2.2); }
    } else if (o.hood) {
      c.fillStyle = o.hood; c.beginPath(); c.arc(0.5, -16.6, 3.4, Math.PI * 0.9, Math.PI * 2.1); c.fill();
    } else {
      c.fillStyle = '#3b2617'; c.beginPath(); c.arc(0.3, -17, 3.1, Math.PI * 1.05, Math.PI * 1.95); c.fill();
    }
    // front arm + weapon
    const sw = o.swing || 0;
    c.save();
    c.translate(2.5, -11.5);
    c.rotate(-0.4 + sw * 1.6);
    c.strokeStyle = SKIN; c.lineWidth = 1.9;
    line(c, 0, 0, 4.5, 2.5);
    c.translate(4.5, 2.5);
    if (o.weapon) o.weapon(c);
    c.restore();
    if (o.shield) {
      c.fillStyle = o.shield; c.strokeStyle = '#3a2a18'; c.lineWidth = 1;
      c.beginPath(); c.arc(3.8, -9.5, 3.8, 0, Math.PI * 2); c.fill(); c.stroke();
      c.fillStyle = o.shieldBoss || '#d9b64a'; circle(c, 3.8, -9.5, 1.1);
    }
  }
  const W = {
    club: c => { c.strokeStyle = '#6b4423'; c.lineWidth = 2.4; line(c, 0, 0, 2, -8); c.fillStyle = '#5b3a1e'; circle(c, 2.2, -8.5, 2); },
    axe: c => { c.strokeStyle = '#6b4423'; c.lineWidth = 1.8; line(c, 0, 0, 1.5, -9); c.fillStyle = '#b8b8c0'; poly(c, [1, -9, 5, -10.5, 5, -6.5, 1.3, -7]); },
    sword: c => { c.strokeStyle = '#d8d8e0'; c.lineWidth = 1.8; line(c, 0, 0, 1, -11); c.strokeStyle = '#7a5a2a'; c.lineWidth = 2; line(c, -1.5, -1, 2.5, -1); },
    spear: c => { c.strokeStyle = '#7b5530'; c.lineWidth = 1.6; line(c, -5, 6, 4, -15); c.fillStyle = '#c8c8d0'; poly(c, [4, -15, 3.2, -19.5, 6, -16]); },
    bow: c => { c.strokeStyle = '#6e4a24'; c.lineWidth = 1.7; c.beginPath(); c.arc(-1, -2, 7, -1.1, 1.1); c.stroke(); c.strokeStyle = '#e8e2d0'; c.lineWidth = 0.7; line(c, 2.2, -8.2, 2.2, 4.2); },
    staff: c => { c.strokeStyle = '#c8a050'; c.lineWidth = 1.8; line(c, -1, 6, 1, -14); c.fillStyle = '#f2d76a'; circle(c, 1, -15, 2); },
    pick: c => { c.strokeStyle = '#6b4423'; c.lineWidth = 1.7; line(c, 0, 0, 1, -9); c.strokeStyle = '#9a9aa4'; c.lineWidth = 1.8; c.beginPath(); c.arc(1, -6, 4.5, -2.4, -0.7); c.stroke(); },
    hoe: c => { c.strokeStyle = '#6b4423'; c.lineWidth = 1.6; line(c, 0, 0, 2, -11); c.strokeStyle = '#8f8f98'; c.lineWidth = 2; line(c, 2, -11, 5.5, -9.5); },
    hammer: c => { c.strokeStyle = '#6b4423'; c.lineWidth = 1.6; line(c, 0, 0, 1, -7); c.fillStyle = '#8c8c94'; c.fillRect(-1.5, -9.5, 5, 3); },
    basket: c => { c.fillStyle = '#b08848'; ellipse(c, 1.5, 0.5, 3.5, 2.5); c.fillStyle = '#c0392b'; circle(c, 0.5, -1, 1); circle(c, 2.5, -0.6, 1); },
    javelin: c => { c.strokeStyle = '#7b5530'; c.lineWidth = 1.4; line(c, -3, 3, 5, -10); c.fillStyle = '#bfbfc7'; poly(c, [5, -10, 4.6, -13, 6.6, -10.8]); },
  };

  function villagerWeapon(u) {
    const o = u.order;
    if (!o) return null;
    if (o.type === 'build') return W.hammer;
    if (o.type === 'attack') return W.axe;
    if (o.type === 'gather') {
