        c.fillStyle = m.wall; c.fillRect(x + 6, y + 6, S - 12, 8); c.fillRect(x + 6, y + S - 12, S - 12, 8);
        c.fillStyle = m.wallD; c.fillRect(x + 6, y + 6, 6, S - 12); c.fillRect(x + S - 12, y + 6, 6, S - 12);
