  function drawWonder(c, x, y, S, color, style, b, t) {
    const prog = b ? (b.built ? 1 : b.progress) : 1;
    const glow = b && b.built ? 0.5 + Math.sin(t * 3) * 0.5 : 0;
    if (style === 'greek') {
      c.fillStyle = '#c9c1ad'; c.fillRect(x + 2, y + S - 22, S - 4, 20);
      c.fillStyle = '#e7e1d2'; c.fillRect(x + 8, y + 30, S - 16, S - 52);
      columns(c, x + 10, y + S - 22, S - 20, 70 * Math.min(1, prog * 1.6), 10, '#f4f0e6');
