  /* ---------- resources ---------- */
  function drawTree(c, r, x, y, sand, t) {
    const v = r.variant % 3;
    shadow(c, x + 2, y + 8, 12, 5);
    const sway = Math.sin(t * 1.3 + r.variant) * 0.8;
    if (sand) {
      c.strokeStyle = '#8a6a40'; c.lineWidth = 3;
