      c.fillStyle = '#3d7f32'; circle(c, x - 4 + sway, y - 17, 7); circle(c, x + 5 + sway, y - 12, 6);
      c.fillStyle = '#58a044'; circle(c, x - 5 + sway, y - 19, 3.2);
    } else if (v === 1) {
      for (let i = 0; i < 3; i++) poly(c, [x - 11 + i * 2 + sway, y - 2 - i * 8, x + 11 - i * 2 + sway, y - 2 - i * 8, x + sway, y - 16 - i * 8], ['#1f5a32', '#276a3a', '#2f7a42'][i]);
    } else {
      c.fillStyle = '#356f28'; circle(c, x + sway, y - 13, 10);
      c.fillStyle = '#4a8a34'; circle(c, x + 3 + sway, y - 16, 7);
      c.fillStyle = '#2a5a20'; circle(c, x - 5 + sway, y - 10, 6);
    }
  }
  function drawResource(c, r, t, sand) {
    const x = r.x, y = r.y;
    const f = r.max ? r.amount / r.max : 1;
    switch (r.type) {
      case 'tree': drawTree(c, r, x, y, sand, t); break;
      case 'bush': {
        shadow(c, x, y + 7, 12, 4);
        c.fillStyle = '#2f6a2a'; circle(c, x - 5, y, 7); circle(c, x + 5, y + 1, 7); circle(c, x, y - 5, 8);
        c.fillStyle = '#3f8a36'; circle(c, x - 2, y - 7, 4);
        c.fillStyle = '#d0304a';
