        for (let i = 0; i < n; i++) { const a = i * 2.3 + r.variant, rr = 3 + (i % 3) * 2.2; circle(c, x + Math.cos(a) * rr, y - 2 + Math.sin(a) * rr * 0.8, 1.6); }
