        shadow(c, x, y + 8, 13 * sc, 4 * sc);
        const rocks = [[-6, 2, 7], [5, 3, 6], [0, -3, 8], [-2, 6, 5]];
        for (const [ox, oy, rs] of rocks) {
          const s = rs * sc;
          poly(c, [x + ox - s, y + oy + s * 0.6, x + ox - s * 0.6, y + oy - s * 0.7, x + ox + s * 0.4, y + oy - s, x + ox + s, y + oy + s * 0.5], base[1], base[0]);
          poly(c, [x + ox - s * 0.6, y + oy - s * 0.7, x + ox + s * 0.4, y + oy - s, x + ox + s * 0.2, y + oy - s * 0.2], base[2]);
        }
        if (r.type === 'gold') { const tw = (Math.sin(t * 3 + r.variant) + 1) / 2; c.fillStyle = `rgba(255,255,220,${tw})`; circle(c, x + 2, y - 4, 1.4); }
        break;
      }
      case 'fish': {
