        const n = Math.max(1, Math.ceil(f * 3));
        for (let i = 0; i < n; i++) {
          const a = t * (0.8 + i * 0.2) + i * 2.1 + r.variant;
          const fx = x + Math.cos(a) * (5 + i * 2), fy = y + Math.sin(a) * (3 + i);
          c.save(); c.translate(fx, fy); c.rotate(a + Math.PI / 2);
