      case 'carcass': {
        const rot = r.rot || 0;
        const base = r.animal === 'elephant' ? '#8c837a' : r.animal === 'lion' ? '#c9964a' : '#c99a5e';
        const col = rot > 0.6 ? shadeColor(base, -0.45) : rot > 0.3 ? shadeColor(base, -0.25) : base;
        c.save(); c.translate(x, y);
        const big = r.animal === 'elephant' ? 1.8 : 1;
        c.fillStyle = 'rgba(120,20,20,0.5)'; ellipse(c, 1, 2, 9 * big, 4 * big);
        c.fillStyle = col; ellipse(c, 0, 0, 7.5 * big, 3.8 * big); circle(c, 8 * big, -1, 2.6 * big);
