    for (const b of blds) g.setRally(b, wx, wy, target && target.id);
    if (blds.length) { this.markers.push({ x: wx, y: wy, t: performance.now() / 1000, color: '#f2d76a' }); Sound.play('click'); }
  }

  /* ---------- placement ---------- */
  startPlacement(type) {
    const p = this.p;
    const st = this.g.buildStatus(p, type);
    if (!st.ok) { this.warn(st.reason); return; }
    if (!p.canAfford(p.bs(type).cost)) { this.warn('Not enough resources for a ' + p.bs(type).name); return; }
    this.placing = { type, tx: 0, ty: 0 };
    this.mode = null;
  }
  updatePlacement(wx, wy) {
    if (!this.placing) return;
    const s = BUILDINGS[this.placing.type].size;
    this.placing.tx = Math.floor(wx / TILE - s / 2 + 0.5);
    this.placing.ty = Math.floor(wy / TILE - s / 2 + 0.5);
  }
  tryPlace(shift) {
    const pl = this.placing, g = this.g;
    if (!pl) return;
    if (pl.type === 'wall') { pl.wallLine = { x0: pl.tx, y0: pl.ty }; return; }
    const r = g.placeBuilding(this.pid, pl.type, pl.tx, pl.ty, true);
    if (!r.ok) { this.warn(r.reason); return; }
    const vills = this.myUnits().filter(u => u.type === 'villager');
    if (vills.length) g.cmdBuild(vills, r.building, false);
    Sound.play('click');
    if (!shift || !this.p.canAfford(this.p.bs(pl.type).cost)) this.placing = null;
  }
  finishWall(shift) {
    const pl = this.placing, g = this.g;
    if (!pl || !pl.wallLine) return;
    const r = g.placeWall(this.pid, pl.wallLine.x0, pl.wallLine.y0, pl.tx, pl.ty, true);
    pl.wallLine = null;
    if (!r.ok) { this.warn(r.reason); return; }
    const vills = this.myUnits().filter(u => u.type === 'villager');
    if (vills.length) g.cmdBuild(vills, r.placed[0], false);
    Sound.play('click');
    if (!shift) this.placing = null;
  }
  warn(text) {
    this.msgs.push({ text, kind: 'warn', t: performance.now() });
    if (this.msgs.length > 7) this.msgs.shift();
    this.renderLog();
    Sound.play('error');
  }

  /* ---------- commands ---------- */
  commands() {
    const g = this.g, p = this.p;
    const ents = this.selEnts();
    if (!ents.length || !p) return [];
    const mine = ents.filter(e => e.owner === this.pid);
    if (!mine.length) return [];
    const out = [];
    const units = mine.filter(e => e.kind === 'unit');
    if (units.length) {
      const vills = units.filter(u => u.type === 'villager');
      if (vills.length && this.page) {
        const list = this.page === 'eco' ? BUILD_ORDER_ECO : BUILD_ORDER_MIL;
        for (const k of list) {
          const st = g.buildStatus(p, k);
          const bs = p.bs(k);
          out.push({
            icon: Sprites.buildingIcon(k, p.color, Math.max(p.age, BUILDINGS[k].age), p.civDef.style, 44),
            state: st.disabled ? 'disabled' : !st.ok ? 'locked' : p.canAfford(bs.cost) ? 'ok' : 'short',
            act: () => this.startPlacement(k),
            tip: `<b>${esc(bs.name)}</b> <span class="age-tag">${AGE_NAMES[BUILDINGS[k].age]}</span><br>${costHTML(bs.cost, p)}<br>${esc(BUILDINGS[k].desc)}${BUILDINGS[k].pop ? '<br>+' + BUILDINGS[k].pop + ' population' : ''}${st.ok ? '' : '<br><span class="bad">' + esc(st.reason) + '</span>'}`,
          });
        }
        while (out.length < 14) out.push(null);
        out.push({ icon: Sprites.glyphIcon('back', 44, 'cmd'), state: 'ok', act: () => { this.page = null; this.cmdSig = ''; }, tip: 'Back' });
        return out;
      }
      if (vills.length) {
        out.push({ icon: Sprites.glyphIcon('buildeco', 44, 'cmd'), state: 'ok', act: () => { this.page = 'eco'; this.cmdSig = ''; }, tip: '<b>Build economic building</b><br>Houses, drop-off sites, farms, Market, Wonder…' });
        out.push({ icon: Sprites.glyphIcon('buildmil', 44, 'cmd'), state: 'ok', act: () => { this.page = 'mil'; this.cmdSig = ''; }, tip: '<b>Build military building</b><br>Barracks, ranges, towers, walls, temples…' });
      }
      const fighters = units.filter(u => g.us(u).atk > 0 || UNITS[u.type].cls === 'priest');
      if (fighters.length && !vills.length) out.push({ icon: Sprites.glyphIcon('attackmove', 44, 'cmd'), state: this.mode === 'attackMove' ? 'active' : 'ok', act: () => { this.mode = 'attackMove'; this.placing = null; }, tip: '<b>Attack-move</b><br>Advance to a point, fighting (or converting) any enemies met on the way. Then left-click the destination.' });
      out.push({ icon: Sprites.glyphIcon('stop', 44, 'cmd'), state: 'ok', act: () => g.cmdStop(units), tip: '<b>Stop</b>' });
      if (units.some(u => UNITS[u.type].cls === 'priest')) out.push({ icon: Sprites.glyphIcon('convert', 44, 'cmd'), state: 'ok', act: () => this.warn('Right-click an enemy unit to begin converting it.'), tip: '<b>Convert</b><br>Right-click an enemy: the priest chants for several seconds (longer against chariots); if uninterrupted the target joins you. Faith must then recharge.' });
      while (out.length < 14) out.push(null);
      out.push({ icon: Sprites.glyphIcon('delete', 44, 'cmd'), state: 'ok', act: () => { for (const u of units) g.deleteEntity(u); }, tip: '<b>Delete</b> selected units' });
      return out;
    }
    const b = mine[0];
    if (b.kind !== 'building') return [];
    const d = BUILDINGS[b.type];
    const sameType = mine.filter(e => e.kind === 'building' && e.type === b.type && e.built);
    const pickB = () => sameType.slice().sort((a, c) => a.queue.length - c.queue.length)[0] || b;
    if (b.built) {
      for (const base of d.trains || []) {
        const st = g.unitStatus(p, base);
        const key = p.resolve(base);
        const us = p.us(key);
        const queued = sameType.reduce((n, bb) => n + bb.queue.filter(q => q.key === base).length, 0);
        out.push({
          icon: Sprites.unitIcon(key, p.color, 44), badge: queued || '',
          state: st.disabled ? 'disabled' : !st.ok ? 'locked' : p.canAfford(us.cost) ? 'ok' : 'short',
          act: (shift) => { for (let i = 0; i < (shift ? 5 : 1); i++) { const r = g.queueTrain(pickB(), base); if (!r.ok) { this.warn(r.reason); break; } } },
          tip: this.unitTip(key, st, us),
        });
      }
      for (const tk of d.research || []) {
        const st = g.techStatus(p, tk);
        if (st.hidden) continue;
        const t = TECHS[tk];
        let reqHTML = '';
        if (t.advance && st.ageReq) {
          reqHTML = '<div class="req">Requires ' + st.ageReq.need + ' of these ' + AGE_NAMES[t.advance - 1] + ' buildings:<br>' + st.ageReq.of.map(k => `<span class="${st.ageReq.have.includes(k) ? 'good' : 'bad'}">${st.ageReq.have.includes(k) ? '✔' : '✘'} ${esc(BUILDINGS[k].name)}</span>`).join('<br>') + '</div>';
          reqHTML += '<div class="req">Unlocks: ' + esc(g.unlocksForAge(p, t.advance).join(', ')) + '</div>';
        }
        out.push({
          icon: Sprites.techIcon(tk, 44),
          state: st.disabled ? 'disabled' : st.reason === 'Researching…' ? 'busy' : !st.ok ? 'locked' : p.canAfford(t.cost) ? 'ok' : 'short',
          act: () => { const r = g.queueResearch(b, tk); if (!r.ok) this.warn(r.reason); else Sound.play('click'); },
          tip: `<b>${esc(t.name)}</b>${t.advance ? '' : ' <span class="age-tag">' + AGE_NAMES[t.age] + '</span>'}<br>${costHTML(t.cost, p)} · ${t.time}s<br>${esc(t.desc || '')}${reqHTML}${st.ok || t.advance ? '' : '<br><span class="bad">' + esc(st.reason) + '</span>'}`,
        });
      }
    }
    while (out.length < 14) out.push(null);
    out.length = 14;
    out.push({ icon: Sprites.glyphIcon('delete', 44, 'cmd'), state: 'ok', act: () => { if (b.type === 'towncenter' && !confirm('Delete your Town Centre?')) return; for (const e of mine) g.deleteEntity(e); }, tip: '<b>Delete</b> building' });
    return out;
  }
  unitTip(key, st, us) {
    const p = this.p, d = UNITS[key];
    const stats = [`HP ${us.hp}`];
    if (us.atk) stats.push(`Attack ${Math.round(us.atk * 10) / 10}${us.atkType === 'pierce' ? ' (pierce)' : us.atkType === 'siege' ? ' (siege)' : ''}`);
    if (us.range) stats.push(`Range ${us.range}`);
    stats.push(`Armour ${us.armorM}/${us.armorP}`);
    stats.push(`Speed ${Math.round(us.speed * 100) / 100}`);
    let bonus = '';
    if (d.bonus) bonus = '<br>Bonus vs: ' + Object.entries(d.bonus).map(([k, v]) => k + ' ×' + v).join(', ');
    return `<b>${esc(us.name)}</b> <span class="age-tag">${AGE_NAMES[d.age]}</span><br>${costHTML(us.cost, p)} · ${d.time}s<br>${esc(d.desc || '')}<br><span class="stats">${stats.join(' · ')}</span>${bonus}${st.ok ? '' : '<br><span class="bad">' + esc(st.reason) + '</span>'}`;
  }
  renderCommands() {
    const cmds = this.commands();
    const sig = cmds.map(c => c ? c.icon + c.state + (c.badge || '') : '-').join('|') + this.mode;
    if (sig === this.cmdSig) return;
    this.cmdSig = sig;
    this.cmdList = cmds;
    let html = '';
    for (let i = 0; i < 15; i++) {
      const c = cmds[i];
      if (!c) { html += '<div class="cmd empty"></div>'; continue; }
      html += `<div class="cmd st-${c.state}" data-i="${i}"><img src="${c.icon}" alt=""><span class="hk">${HOTKEYS[i]}</span>${c.badge ? `<span class="badge">${c.badge}</span>` : ''}${c.state === 'disabled' ? '<span class="x">✕</span>' : c.state === 'locked' ? '<span class="lock">🔒</span>' : ''}</div>`;
    }
    this.dom.cmds.innerHTML = html;
  }
  runCommand(i, shift) {
    const c = this.cmdList && this.cmdList[i];
    if (!c) return;
    if (c.state === 'disabled') { this.warn('Not available to the ' + this.p.civName + '.'); return; }
    c.act(shift);
    this.cmdSig = '';
  }

  /* ---------- info panel ---------- */
  renderInfo() {
    const g = this.g;
    const ents = this.selEnts();
    let html = '';
    if (!ents.length) {
      html = this.overviewHTML();
    } else if (ents.length > 1) {
      html = '<div class="multi">' + ents.slice(0, 40).map(e => {
        const icon = e.kind === 'unit' ? Sprites.unitIcon(e.type, g.players[e.owner].color, 34) : Sprites.buildingIcon(e.type, g.players[e.owner].color, g.players[e.owner].age, g.players[e.owner].civDef ? g.players[e.owner].civDef.style : 'desert', 34);
        const f = e.hp / e.maxHp;
        return `<div class="mi" data-id="${e.id}"><img src="${icon}"><div class="mhp"><div style="width:${Math.round(f * 100)}%;background:${f > 0.5 ? '#3ec43e' : f > 0.25 ? '#e0c030' : '#e04030'}"></div></div></div>`;
      }).join('') + '</div>';
    } else html = this.singleHTML(ents[0]);
    if (html !== this.infoSig) { this.infoSig = html; this.dom.info.innerHTML = html; }
  }
  overviewHTML() {
    if (!this.p) return '<div class="hint">Spectating. Click any unit or building to inspect it.</div>';
    const p = this.p, g = this.g;
    const civ = p.civDef;
    let next = '';
    if (p.age < 3) {
      const st = g.ageReqStatus(p, p.age + 1);
      const t = TECHS[AGE_REQ[p.age + 1].tech];
      next = `<div class="next-age"><b>Next: ${AGE_NAMES[p.age + 1]}</b> — research at the Town Centre for ${costHTML(t.cost, p)}<br>Needs ${st.need} of: ${st.of.map(k => `<span class="${st.have.includes(k) ? 'good' : 'bad'}">${st.have.includes(k) ? '✔' : '✘'} ${esc(BUILDINGS[k].name)}</span>`).join(', ')}</div>`;
    } else next = '<div class="next-age"><b>Iron Age reached.</b> Build a Wonder (1000 wood, gold and stone) for a monument victory, or conquer your foes.</div>';
    return `<div class="civ-line"><b style="color:${p.color}">${esc(p.name)}</b> — ${esc(civ.name)}, ${AGE_NAMES[p.age]}</div>${next}<div class="bonus-line">${civ.bonuses.map(esc).join(' · ')}</div><div class="hint">Left-click to select · drag to box-select · right-click to act · H: Town Centre · .: idle villager</div>`;
  }
  singleHTML(e) {
    const g = this.g, op = g.players[e.owner];
    const hpBar = (v, m, col) => `<div class="bar"><div style="width:${Math.round(clamp(v / m, 0, 1) * 100)}%;background:${col || (v / m > 0.5 ? '#3ec43e' : v / m > 0.25 ? '#e0c030' : '#e04030')}"></div><span>${Math.ceil(v)} / ${Math.ceil(m)}</span></div>`;
    const ownerLine = e.owner ? `<div class="owner" style="color:${op.color}">${esc(op.name)} · ${esc(op.civName)}</div>` : '';
    if (e.kind === 'resource') {
      const d = RESOURCE_DEFS[e.type];
      const icon = Sprites.resourceIcon(e.type, 64);
      let extra = `Gatherers: ${e.gc}`;
      if (e.type === 'carcass') extra += `<br><span class="bad">Rotting — loses ${CARCASS_ROT} food every second. Butcher it quickly!</span>`;
      if (e.type === 'fish') extra += '<br>Harvested by Fishing Boats; returned to a Dock.';
      else if (e.type === 'tree') extra += '<br>Felled trees are removed from the map. Drop-off: Storage Pit or Town Centre.';
      else if (e.type === 'bush') extra += '<br>Foraged by villagers. Drop-off: Granary or Town Centre.';
      else if (e.type === 'gold' || e.type === 'stone') extra += '<br>Veins run out. Drop-off: Storage Pit or Town Centre.';
      return `<div class="single"><img class="portrait" src="${icon}"><div class="det"><div class="nm">${d.name}</div>${hpBar(e.amount, e.max, RES_COLORS[d.res])}<div class="sub">${Math.ceil(e.amount)} ${d.res} remaining</div><div class="sub">${extra}</div></div></div>`;
    }
    if (e.kind === 'unit') {
      const s = g.us(e), d = UNITS[e.type];
      const icon = Sprites.unitIcon(e.type, op.color, 64);
      let task = '';
      if (d.animal) task = `${d.animal === 'flee' ? 'Skittish' : d.animal === 'aggressive' ? 'Aggressive predator' : 'Fights back when attacked'} · ${d.food} food when killed — hunted animals must then be butchered before they rot.`;
      else if (e.type === 'villager' || e.type === 'fishingboat') {
        const o = e.order;
        let job = 'Idle';
        if (o) {
          if (o.type === 'gather') job = (o.cat ? CAT_LABEL[o.cat] : (g.ents.get(o.target) && g.ents.get(o.target).kind === 'unit' ? 'Hunter' : 'Gatherer')) + (o.state === 'return' ? ' (returning)' : '');
          else if (o.type === 'build') { const b = g.ents.get(o.target); job = b && b.built ? 'Repairing' : 'Builder'; }
          else if (o.type === 'move') job = 'Moving';
          else if (o.type === 'attack') job = 'Fighting';
        }
        task = `<b>${job}</b>${e.carry > 0.5 ? ` · carrying ${Math.floor(e.carry)} ${e.carryRes}` : ''}`;
      } else if (d.cls === 'priest') {
        const o = e.order;
        task = `Faith ${Math.floor(e.faith)}%` + (o && o.type === 'convert' ? (o.waiting ? ' · waiting for faith' : ` · converting (${Math.round(100 * Math.min(1, o.chan / Math.max(0.1, o.need || 6)))}%)`) : o && o.type === 'heal' ? ' · healing' : '');
        task += `<div class="bar faith"><div style="width:${Math.floor(e.faith)}%"></div></div>`;
      } else if (e.order) task = { attack: 'Attacking', move: 'Moving', attackMove: 'Advancing' }[e.order.type] || '';
      const stats = [];
      if (s.atk) stats.push(`⚔ ${Math.round(s.atk * 10) / 10}${s.atkType === 'pierce' ? 'p' : s.atkType === 'siege' ? 's' : ''}`);
      if (s.range) stats.push(`➶ ${s.range}`);
      if (!d.animal) stats.push(`🛡 ${s.armorM}/${s.armorP}`);
      stats.push(`👁 ${s.los}`);
      return `<div class="single"><img class="portrait" src="${icon}"><div class="det"><div class="nm">${esc(s.name)}</div>${ownerLine}${hpBar(e.hp, e.maxHp)}<div class="sub stats">${stats.join(' &nbsp; ')}</div><div class="sub">${task}</div></div></div>`;
    }
    // building
    const bs = g.bs(e), d = BUILDINGS[e.type];
    const icon = Sprites.buildingIcon(e.type, op.color, op.age, op.civDef ? op.civDef.style : 'desert', 64);
    let extra = '';
    if (!e.built) extra = `<div class="sub">Under construction: ${Math.floor(e.progress * 100)}%${d.wonder ? ' — every player has been warned!' : ''}</div><div class="bar"><div style="width:${e.progress * 100}%;background:#e0b040"></div></div>`;
    if (e.type === 'farm' && e.built) extra += `<div class="sub">${Math.ceil(e.food)} food left (farm is exhausted at 0 and must be rebuilt)</div><div class="bar"><div style="width:${100 * e.food / e.maxFood}%;background:#a6c03a"></div></div>`;
    if (d.wonder && e.built) extra += `<div class="sub wonder-cd">Victory in ${fmtTime(e.wonderT)}</div>`;
    if (d.drop) extra += `<div class="sub">Accepts: ${d.drop.map(k => DROP_LABEL[k]).join(', ')}</div>`;
    if (d.pop) extra += `<div class="sub">Supports ${d.pop} population</div>`;
    if (bs.atk) extra += `<div class="sub">⚔ ${bs.atk} · range ${bs.range}</div>`;
    if (e.built && e.queue.length && (e.owner === this.pid || !this.pid)) {
      extra += '<div class="queue">' + e.queue.map((q, i) => {
        const ic = q.kind === 'unit' ? Sprites.unitIcon(op.resolve(q.key), op.color, 34) : Sprites.techIcon(q.key, 34);
        return `<div class="qi" data-q="${i}" title="Click to cancel"><img src="${ic}">${i === 0 ? `<div class="qp" style="width:${Math.round(q.progress * 100)}%"></div>` : ''}</div>`;
      }).join('') + (e.queue[0].blocked ? '<span class="bad"> Need more houses!</span>' : '') + '</div>';
    }
    if (e.type === 'towncenter' && op.age < 3 && e.owner === this.pid) {
      const st = g.ageReqStatus(op, op.age + 1);
      extra += `<div class="sub">${AGE_NAMES[op.age + 1]} needs ${st.need} of: ${st.of.map(k => `<span class="${st.have.includes(k) ? 'good' : 'bad'}">${esc(BUILDINGS[k].name)}</span>`).join(', ')}</div>`;
    }
    return `<div class="single"><img class="portrait" src="${icon}"><div class="det"><div class="nm">${esc(bs.name)}</div>${ownerLine}${hpBar(e.hp, e.maxHp)}${extra}</div></div>`;
  }

  /* ---------- top bar ---------- */
  buildTopBar() {
    const t = this.dom.top;
    t.innerHTML = `
      <div class="res" id="r-food" title="Food"><i class="ri ri-food"></i><span></span></div>
      <div class="res" id="r-wood" title="Wood"><i class="ri ri-wood"></i><span></span></div>
      <div class="res" id="r-gold" title="Gold"><i class="ri ri-gold"></i><span></span></div>
      <div class="res" id="r-stone" title="Stone"><i class="ri ri-stone"></i><span></span></div>
      <div class="res" id="r-pop" title="Population / housing"><i class="ri ri-pop"></i><span></span></div>
      <div id="age-label"></div>
      <div class="spacer"></div>
      <button id="btn-idle" title="Select idle villager (.)">Idle: 0</button>
      <button id="btn-score" title="Scoreboard (Tab)">Scores</button>
      <button id="btn-civ" title="Civilisations">Civs</button>
      <div id="clock">0:00</div>
      <button id="btn-speed" title="Game speed (+/-)">1.5×</button>
      <button id="btn-menu" title="Pause menu (F10 / P)">Menu</button>`;
    this.$('btn-idle').onclick = () => this.nextIdle();
    this.$('btn-score').onclick = () => { this.scoreVisible = !this.scoreVisible; };
    this.$('btn-civ').onclick = () => this.app.showCivs();
    this.$('btn-speed').onclick = () => this.app.cycleSpeed(1);
    this.$('btn-menu').onclick = () => this.app.togglePause(true);
  }
  updateTopBar() {
    const g = this.g;
    const p = this.p || g.players[1];
    for (const k of RES_KEYS) this.$('r-' + k).querySelector('span').textContent = Math.floor(p.res[k]);
    const pe = this.$('r-pop');
    pe.querySelector('span').textContent = p.pop + '/' + p.popCap;
    pe.classList.toggle('warn', p.pop >= p.popCap);
    let age = `<b>${AGE_NAMES[p.age]}</b>`;
    for (const tc of g.buildings) if (tc.owner === p.id && tc.queue.length && tc.queue[0].kind === 'tech' && TECHS[tc.queue[0].key].advance) age += ` → ${AGE_NAMES[TECHS[tc.queue[0].key].advance]} ${Math.floor(tc.queue[0].progress * 100)}%`;
    if (!this.pid) age = 'Spectating · ' + age + ' (' + esc(p.name) + ')';
    this.$('age-label').innerHTML = age;
    const idle = this.pid ? g.units.filter(u => !u.dead && u.owner === this.pid && u.type === 'villager' && !u.order).length : 0;
    const bi = this.$('btn-idle');
    bi.textContent = 'Idle: ' + idle; bi.classList.toggle('warn', idle > 0);
    this.$('clock').textContent = fmtTime(g.time);
    this.$('btn-speed').textContent = this.app.speed + '×';
  }
  renderBanners() {
    const g = this.g;
    const ws = g.buildings.filter(b => !b.dead && BUILDINGS[b.type].wonder);
    const html = ws.map(b => {
      const p = g.players[b.owner];
      const mine = b.owner === this.pid;
      return `<div class="wb ${b.built ? 'standing' : ''}" style="border-color:${p.color}" data-x="${b.x}" data-y="${b.y}"><span class="dot" style="background:${p.color}"></span>${esc(p.name)}'s Wonder (${esc(p.civName)}) — ${b.built ? '<b>STANDING: victory in ' + fmtTime(b.wonderT) + '</b>' : 'under construction ' + Math.floor(b.progress * 100) + '%'}${mine ? ' (yours)' : ''}</div>`;
    }).join('');
    if (html !== this.bannerSig) { this.bannerSig = html; this.dom.banners.innerHTML = html; }
  }
  renderScore() {
    const g = this.g, sb = this.dom.score;
    if (!this.scoreVisible) { sb.style.display = 'none'; return; }
    sb.style.display = 'block';
    const rows = g.players.filter(p => p.id).map(p => {
      const showRes = !this.pid || g.allied(p.id, this.pid);
      const score = Math.floor((p.stats.gathered.food + p.stats.gathered.wood + p.stats.gathered.gold + p.stats.gathered.stone) / 10 + p.stats.killed * 4 + p.stats.razed * 10 + p.age * 100 + p.stats.techs * 10);
      return `<tr class="${p.alive ? '' : 'dead'}"><td><span class="dot" style="background:${p.color}"></span>${esc(p.name)}</td><td>${esc(p.civName)}</td><td>${['Stone', 'Tool', 'Bronze', 'Iron'][p.age]}</td><td>${p.pop}</td><td>${score}</td>${showRes ? `<td>${RES_KEYS.map(k => Math.floor(p.res[k])).join('/')}</td>` : '<td>–</td>'}</tr>`;
    }).join('');
    const html = `<table><tr><th>Player</th><th>Civ</th><th>Age</th><th>Pop</th><th>Score</th><th>F/W/G/S</th></tr>${rows}</table>`;
    if (html !== this.scoreSig) { this.scoreSig = html; sb.innerHTML = html; }
  }

  bindPanels() {
    const g = this.g;
    this.dom.cmds.addEventListener('mousedown', e => {
      const el = e.target.closest('.cmd'); if (!el || el.dataset.i == null) return;
      e.preventDefault(); e.stopPropagation();
      this.runCommand(+el.dataset.i, e.shiftKey);
    });
    this.dom.cmds.addEventListener('mousemove', e => {
      const el = e.target.closest('.cmd');
      const c = el && el.dataset.i != null && this.cmdList && this.cmdList[+el.dataset.i];
      if (!c) { this.dom.tip.style.display = 'none'; return; }
      this.dom.tip.innerHTML = c.tip; this.dom.tip.style.display = 'block';
    });
    this.dom.cmds.addEventListener('mouseleave', () => { this.dom.tip.style.display = 'none'; });
    this.dom.info.addEventListener('mousedown', e => {
      const q = e.target.closest('.qi');
      if (q && this.sel.length === 1) {
        const b = g.ents.get(this.sel[0]);
        if (b && b.owner === this.pid) { g.cancelQueue(b, +q.dataset.q); Sound.play('click'); }
        e.preventDefault(); return;
      }
      const mi = e.target.closest('.mi');
      if (mi) {
        const id = +mi.dataset.id;
        if (e.shiftKey) this.setSel(this.sel.filter(i => i !== id)); else this.setSel([id]);
        e.preventDefault();
      }
    });
    this.dom.log.addEventListener('mousedown', e => {
      const m = e.target.closest('.msg'); if (!m) return;
      const msg = this.msgs[+m.dataset.i];
      if (msg && msg.x != null) this.r.centerOn(msg.x, msg.y);
    });
    this.dom.banners.addEventListener('mousedown', e => {
      const w = e.target.closest('.wb'); if (!w) return;
      this.r.centerOn(+w.dataset.x, +w.dataset.y);
    });
  }

  /* ---------- helpers for hotkeys ---------- */
  nextIdle() {
    const idle = this.g.units.filter(u => !u.dead && u.owner === this.pid && u.type === 'villager' && !u.order);
    if (!idle.length) return;
    this.idleIdx = ((this.idleIdx || 0) + 1) % idle.length;
    const u = idle[this.idleIdx];
    this.setSel([u.id]);
    this.r.centerOn(u.x, u.y);
  }
  selectTC() {
    const tcs = this.g.buildings.filter(b => !b.dead && b.owner === this.pid && b.type === 'towncenter');
    if (!tcs.length) return;
    this.tcIdx = ((this.tcIdx || 0) + 1) % tcs.length;
    const b = tcs[this.tcIdx];
    this.setSel([b.id]); this.r.centerOn(b.x, b.y);
  }
  group(n, set) {
    if (set) { this.groups[n] = this.sel.slice(); this.warn && this.msgs.push({ text: 'Group ' + n + ' assigned.', kind: 'info', t: performance.now() }); this.renderLog(); return; }
    const ids = (this.groups[n] || []).filter(id => { const e = this.g.ents.get(id); return e && !e.dead && e.owner === this.pid; });
    if (!ids.length) return;
    const now = performance.now();
    if (this.lastGroup === n && now - this.lastGroupT < 400) {
      const e = this.g.ents.get(ids[0]); this.r.centerOn(e.x, e.y);
    }
    this.lastGroup = n; this.lastGroupT = now;
    this.setSel(ids);
  }

  update(dt) {
    this.tAcc += dt;
    this.pruneSel();
    this.markers = this.markers.filter(m => performance.now() / 1000 - m.t < 0.6);
    if (this.tAcc >= 0.12) {
      this.tAcc = 0;
      this.updateTopBar();
      this.renderInfo();
      this.renderCommands();
      this.renderBanners();
      this.renderScore();
      this.renderLog();
    }
  }
}
