/* Shared helpers: seeded RNG, value noise, binary heap, formatting. No DOM access. */

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash2(x, y) {
  let h = (x * 374761393 + y * 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

class ValueNoise {
  constructor(rng) {
    this.perm = new Uint8Array(512);
    this.vals = new Float32Array(256);
    const p = [];
    for (let i = 0; i < 256; i++) { p.push(i); this.vals[i] = rng(); }
    for (let i = 255; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = p[i]; p[i] = p[j]; p[j] = t; }
    for (let i = 0; i < 512; i++) this.perm[i] = p[i & 255];
  }
  lattice(ix, iy) { return this.vals[this.perm[(this.perm[ix & 255] + iy) & 255]]; }
  noise(x, y) {
    const ix = Math.floor(x), iy = Math.floor(y);
    const fx = x - ix, fy = y - iy;
    const sx = fx * fx * (3 - 2 * fx), sy = fy * fy * (3 - 2 * fy);
    const a = this.lattice(ix, iy), b = this.lattice(ix + 1, iy);
    const c = this.lattice(ix, iy + 1), d = this.lattice(ix + 1, iy + 1);
    const top = a + (b - a) * sx, bot = c + (d - c) * sx;
    return top + (bot - top) * sy;
  }
  fbm(x, y, oct = 3) {
    let t = 0, amp = 1, f = 1, norm = 0;
    for (let o = 0; o < oct; o++) {
      t += this.noise(x * f + o * 17.31, y * f + o * 9.17) * amp;
      norm += amp; amp *= 0.5; f *= 2;
    }
    return t / norm;
  }
}

class MinHeap {
  constructor() { this.ids = []; this.keys = []; }
  get size() { return this.ids.length; }
  clear() { this.ids.length = 0; this.keys.length = 0; }
  push(id, key) {
    const ids = this.ids, keys = this.keys;
    let i = ids.length;
    ids.push(id); keys.push(key);
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (keys[p] <= key) break;
      ids[i] = ids[p]; keys[i] = keys[p];
      i = p;
    }
    ids[i] = id; keys[i] = key;
  }
  pop() {
    const ids = this.ids, keys = this.keys;
    const top = ids[0];
    const lastId = ids.pop(), lastKey = keys.pop();
    const n = ids.length;
    if (n > 0) {
      let i = 0;
      for (;;) {
        let c = 2 * i + 1;
        if (c >= n) break;
        if (c + 1 < n && keys[c + 1] < keys[c]) c++;
        if (keys[c] >= lastKey) break;
        ids[i] = ids[c]; keys[i] = keys[c];
        i = c;
      }
      ids[i] = lastId; keys[i] = lastKey;
    }
    return top;
  }
}

function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
function lerp(a, b, t) { return a + (b - a) * t; }
function dist(ax, ay, bx, by) { return Math.hypot(bx - ax, by - ay); }

function fmtTime(sec) {
  sec = Math.max(0, Math.floor(sec));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
  const mm = (h > 0 && m < 10 ? '0' : '') + m;
  return (h > 0 ? h + ':' : '') + mm + ':' + (s < 10 ? '0' : '') + s;
}

function costText(cost) {
  const out = [];
  for (const k of ['food', 'wood', 'gold', 'stone']) if (cost && cost[k]) out.push(cost[k] + ' ' + k);
  return out.join(', ') || 'free';
}

function shuffle(arr, rng) {
  for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
  return arr;
}

function shadeColor(hex, amt) {
  // amt in [-1,1]; negative darkens, positive lightens
  const n = parseInt(hex.slice(1), 16);
  let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  if (amt < 0) { r *= 1 + amt; g *= 1 + amt; b *= 1 + amt; }
  else { r += (255 - r) * amt; g += (255 - g) * amt; b += (255 - b) * amt; }
  return '#' + ((1 << 24) | (Math.round(r) << 16) | (Math.round(g) << 8) | Math.round(b)).toString(16).slice(1);
}
"},{"path":"tools/headless.js","type":"text/javascript","text":"// Headless simulation harness: node tools/headless.js [minutes] [seed] [mapType] [players]
// Runs AI-only games with the real game logic to check economy, ages, waves and victory.
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const root = path.join(__dirname, '..');
const ctx = { console, Math, Date, setTimeout, Set, Map };
ctx.window = ctx;
vm.createContext(ctx);
for (const f of ['util.js', 'data.js', 'map.js', 'pathfinding.js', 'game.js', 'ai.js']) {
  vm.runInContext(fs.readFileSync(path.join(root, 'js', f), 'utf8'), ctx, { filename: f });
}

const minutes = +process.argv[2] || 30;
const seed = +process.argv[3] || 12345;
const mapType = process.argv[4] || 'inland';
const nPlayers = +process.argv[5] || 4;
const civs = ['egyptians', 'greeks', 'babylonians', 'persians', 'assyrians', 'phoenicians', 'yamato', 'shang'];
const diffs = ['hard', 'normal', 'hard', 'normal', 'easy', 'hard'];

const players = [];
for (let i = 0; i < nPlayers; i++) players.push({ civ: civs[(i + seed) % civs.length], ai: true, difficulty: diffs[i], name: 'AI' + (i + 1) });

const t0 = Date.now();
const game = vm.runInContext(`new Game(${JSON.stringify({ seed, mapType, mapSize: 'medium', players, popLimit: 75, wonderTime: 300, observer: true })})`, ctx);
console.log('map generated in', Date.now() - t0, 'ms; units', game.units.length, 'resources', game.resources.length);

const counts = {};
game.on('message', m => {
  const k = m.kind;
  counts[k] = (counts[k] || 0) + 1;
  if (k === 'age' && /advanced/.test(m.text) || k === 'wonder' || /defeated|wave|Wonder/.test(m.text)) console.log(`[${fmt(game.time)}] ${m.text}`);
});
game.on('gameover', e => console.log(`[${fmt(game.time)}] GAME OVER team ${e.team} by ${e.reason}`));
function fmt(s) { return Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0'); }

const ticks = minutes * 60 / 0.05;
let slow = 0;
const tStart = Date.now();
for (let i = 0; i < ticks; i++) {
  const a = Date.now();
  game.step();
  const el = Date.now() - a;
  if (el > 30) slow++;
  if (i % (20 * 120) === 0 || i === ticks - 1) {
    console.log(`--- t=${fmt(game.time)}  units=${game.units.length} proj=${game.projectiles.length}`);
    for (const p of game.players) {
      if (!p.id) continue;
      const vills = game.units.filter(u => u.owner === p.id && u.type === 'villager');
      const idle = vills.filter(u => !u.order).length;
      const mil = game.units.filter(u => u.owner === p.id && !['villager', 'fishingboat'].includes(u.type)).length;
      const boats = game.units.filter(u => u.owner === p.id && u.type === 'fishingboat').length;
      const bl = {};
      for (const b of game.buildings) if (b.owner === p.id) bl[b.type] = (bl[b.type] || 0) + 1;
      const tasks = {};
      for (const v of vills) { const k = v.order ? (v.order.type === 'gather' ? (v.order.cat || '?') : v.order.type) : 'idle'; tasks[k] = (tasks[k] || 0) + 1; }
      const r = p.res, gth = p.stats.gathered;
      console.log(`P${p.id} ${p.civ.padEnd(11)} ${p.difficulty.padEnd(6)} ${p.alive ? AGE_NAMES_(p.age) : 'DEAD'} pop ${p.pop}/${p.popCap} vil ${vills.length} (idle ${idle}) mil ${mil} boats ${boats} ` +
        `res F${r.food | 0} W${r.wood | 0} G${r.gold | 0} S${r.stone | 0} gathered F${gth.food | 0} W${gth.wood | 0} G${gth.gold | 0} S${gth.stone | 0} kills ${p.stats.killed} lost ${p.stats.lost} conv ${p.stats.converted} techs ${p.stats.techs}`);
      console.log('    tasks', JSON.stringify(tasks), 'bld', JSON.stringify(bl));
    }
  }
  if (game.over && i % 20 === 0) { console.log('over'); break; }
}
function AGE_NAMES_(a) { return ['Stone', 'Tool', 'Bronze', 'Iron'][a].padEnd(6); }
console.log('sim time', (Date.now() - tStart) / 1000, 's; slow ticks', slow, 'messages', JSON.stringify(counts));
"}]}
